CONTENTS = {'app/routes/admin.py': 'from __future__ import annotations\nfrom app.services.search_providers import serper_status\n\nfrom pathlib import Path\nfrom urllib.parse import urlencode\n\nfrom fastapi import APIRouter, Request\nfrom fastapi.responses import FileResponse, HTMLResponse, JSONResponse, RedirectResponse, Response\nfrom sqlalchemy import func, or_, select\nfrom sqlalchemy.exc import IntegrityError\nfrom sqlalchemy.orm import selectinload\n\nfrom ..config import settings\nfrom ..database import SessionLocal\nfrom ..models import AdminUser, Disaster, DiscoveryCandidate, MissingPerson, Source, Submission\nfrom ..security import verify_password\nfrom ..services.discovery import discover_candidates, generate_queries, google_search_url\nfrom ..services.wide_discovery import collect_known_source_scopes, generate_wide_queries, run_wide_discovery\nfrom ..services.search_providers import SearchProviderUnavailable, brave_status\nfrom ..services.candidate_extract import candidate_mentions_multiple_people, extract_candidate_people_names, extract_candidate_prefill\nfrom ..services.ai_review import build_free_ai_review_prompt, parse_free_ai_review\nfrom ..services.master_records import apply_submission_to_master\nfrom ..services.duplicates import find_duplicates\nfrom ..services.exports import build_csv, build_xlsx\nfrom ..services.files import save_image\nfrom ..services.source_images import discover_public_post_image, discover_public_post_text, download_public_source_image, is_allowed_public_image_url\nfrom ..services.source_ocr import extract_ocr_text, ocr_available\nfrom ..services.normalization import affected_location_match, canonicalize_url, detect_platform\nfrom ..services.share_cards import build_share_card\nfrom .common import admin_gate, audit, next_case_number, parse_date, parse_int, parse_time, render\n\nrouter = APIRouter()\n\n\ndef _normalize_gender(value) -> str | None:\n    folded = str(value or "").strip().casefold()\n    if folded in {"male", "m", "पुरुष"}:\n        return "Male"\n    if folded in {"female", "f", "महिला"}:\n        return "Female"\n    return None\n\n\ndef _exact_name_matches(db, disaster_id: int, name: str) -> list[MissingPerson]:\n    folded = name.strip().casefold()\n    if not folded:\n        return []\n    people = db.scalars(\n        select(MissingPerson).where(\n            MissingPerson.disaster_id == disaster_id,\n            MissingPerson.archived.is_(False),\n        )\n    ).all()\n    return [\n        person\n        for person in people\n        if person.name.strip().casefold() == folded\n        or (person.name_ne and person.name_ne.strip().casefold() == folded)\n    ]\n\n\ndef _pending_name_matches(db, disaster_id: int, name: str) -> list[Submission]:\n    folded = name.strip().casefold()\n    if not folded:\n        return []\n    submissions = db.scalars(\n        select(Submission).where(\n            Submission.disaster_id == disaster_id,\n            Submission.status == "pending",\n        )\n    ).all()\n    return [\n        item for item in submissions\n        if (item.name or "").strip().casefold() == folded\n    ]\n\n\n@router.get("/admin/media/{filename}")\ndef admin_media(request: Request, filename: str):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    if Path(filename).name != filename:\n        return HTMLResponse("Not found", status_code=404)\n    with SessionLocal() as db:\n        referenced = db.scalar(\n            select(func.count()).select_from(Submission).where(Submission.photo_path == filename)\n        ) or db.scalar(\n            select(func.count()).select_from(MissingPerson).where(MissingPerson.photo_path == filename)\n        )\n        if not referenced:\n            return HTMLResponse("Not found", status_code=404)\n    path = settings.upload_dir / filename\n    if not path.is_file():\n        return HTMLResponse("Not found", status_code=404)\n    return FileResponse(path)\n\n\n@router.get("/admin/login", response_class=HTMLResponse)\ndef login_page(request: Request):\n    return render(request, "admin_login.html", error=None)\n\n\n@router.post("/admin/login", response_class=HTMLResponse)\nasync def login(request: Request):\n    form = await request.form()\n    username = str(form.get("username") or "")\n    password = str(form.get("password") or "")\n    with SessionLocal() as db:\n        admin = db.scalar(select(AdminUser).where(AdminUser.username == username, AdminUser.active.is_(True)))\n        if admin is None or not verify_password(password, admin.password_hash):\n            return render(request, "admin_login.html", error="Invalid credentials")\n        request.session["admin"] = admin.username\n        audit(db, request, "login", "admin", admin.id)\n        db.commit()\n    return RedirectResponse("/admin", status_code=303)\n\n\n@router.post("/admin/logout")\ndef logout(request: Request):\n    request.session.clear()\n    return RedirectResponse("/admin/login", status_code=303)\n\n\n@router.get("/admin", response_class=HTMLResponse)\ndef admin_dashboard(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        stats = {\n            "people": db.scalar(select(func.count(MissingPerson.id)).where(MissingPerson.archived.is_(False))) or 0,\n            "published": db.scalar(\n                select(func.count(MissingPerson.id)).where(\n                    MissingPerson.published.is_(True), MissingPerson.archived.is_(False)\n                )\n            )\n            or 0,\n            "pending": db.scalar(select(func.count(Submission.id)).where(Submission.status == "pending")) or 0,\n            "candidates": db.scalar(\n                select(func.count(DiscoveryCandidate.id)).where(DiscoveryCandidate.status == "new")\n            )\n            or 0,\n            "sources": db.scalar(select(func.count(Source.id))) or 0,\n        }\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_dashboard.html", stats=stats, disasters=disasters)\n\n\n@router.get("/admin/events", response_class=HTMLResponse)\ndef admin_events(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_events.html", disasters=disasters, error=None)\n\n\n@router.post("/admin/events")\nasync def admin_event_create(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    code = str(form.get("code") or "").strip().upper()\n    name = str(form.get("name") or "").strip()\n    start_date = parse_date(form.get("start_date"))\n    if not code or not name or not start_date:\n        return RedirectResponse("/admin/events", status_code=303)\n    with SessionLocal() as db:\n        disaster = Disaster(\n            code=code,\n            name=name,\n            disaster_type=str(form.get("disaster_type") or "flood").strip(),\n            start_date=start_date,\n            affected_locations=str(form.get("affected_locations") or "").strip(),\n            active=True,\n        )\n        db.add(disaster)\n        try:\n            db.flush()\n            audit(db, request, "create_event", "disaster", disaster.id, name)\n            db.commit()\n        except IntegrityError:\n            db.rollback()\n    return RedirectResponse("/admin/events", status_code=303)\n\n\n@router.post("/admin/events/{disaster_id}/update")\nasync def admin_event_update(request: Request, disaster_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id)\n        if disaster is None:\n            return HTMLResponse("Not found", status_code=404)\n        disaster.name = str(form.get("name") or disaster.name).strip()\n        disaster.disaster_type = str(form.get("disaster_type") or disaster.disaster_type).strip()\n        disaster.affected_locations = str(form.get("affected_locations") or "").strip()\n        disaster.active = str(form.get("active") or "") == "on"\n        audit(db, request, "update_event", "disaster", disaster.id, disaster.name)\n        db.commit()\n    return RedirectResponse("/admin/events", status_code=303)\n\n\n@router.get("/admin/people", response_class=HTMLResponse)\ndef admin_people(request: Request, disaster_id: int | None = None, q: str = ""):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        stmt = (\n            select(MissingPerson)\n            .options(selectinload(MissingPerson.sources))\n            .order_by(MissingPerson.created_at.desc())\n        )\n        if disaster_id:\n            stmt = stmt.where(MissingPerson.disaster_id == disaster_id)\n        if q.strip():\n            pattern = f"%{q.strip()}%"\n            stmt = stmt.where(\n                or_(\n                    MissingPerson.name.ilike(pattern),\n                    MissingPerson.name_ne.ilike(pattern),\n                    MissingPerson.case_number.ilike(pattern),\n                )\n            )\n        people = list(db.scalars(stmt.limit(500)).all())\n        return render(\n            request,\n            "admin_people.html",\n            people=people,\n            disasters=disasters,\n            selected_disaster=disaster_id,\n            q=q,\n        )\n\n\n@router.get("/admin/people/{person_id}", response_class=HTMLResponse)\ndef admin_person(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.scalar(\n            select(MissingPerson)\n            .options(selectinload(MissingPerson.sources))\n            .where(MissingPerson.id == person_id)\n        )\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        merge_targets = list(\n            db.scalars(\n                select(MissingPerson).where(\n                    MissingPerson.disaster_id == person.disaster_id,\n                    MissingPerson.id != person.id,\n                    MissingPerson.archived.is_(False),\n                ).order_by(MissingPerson.name)\n            ).all()\n        )\n        return render(\n            request,\n            "admin_person.html",\n            person=person,\n            error=None,\n            public_url=f"{settings.public_base_url}/person/{person.case_number}",\n            merge_targets=merge_targets,\n        )\n\n\n@router.post("/admin/people/{person_id}/edit")\nasync def admin_person_edit(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        person.name = str(form.get("name") or person.name).strip()\n        person.name_ne = str(form.get("name_ne") or "").strip() or None\n        person.age = parse_int(form.get("age"))\n        person.gender = _normalize_gender(form.get("gender"))\n        person.last_seen_date = parse_date(form.get("last_seen_date"))\n        person.last_seen_time = parse_time(form.get("last_seen_time"))\n        person.last_seen_location = str(form.get("last_seen_location") or "").strip()\n        person.clothing = str(form.get("clothing") or "").strip() or None\n        person.identification_details = str(form.get("identification_details") or "").strip() or None\n        person.public_contact_number = str(form.get("public_contact_number") or "").strip() or None\n        person.residential_address_private = str(form.get("residential_address_private") or "").strip() or None\n        audit(db, request, "edit_person", "person", person.id)\n        db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/publish")\ndef admin_publish(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person:\n            person.published = not person.published\n            audit(db, request, "publish_toggle", "person", person.id, str(person.published))\n            db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/archive")\ndef admin_archive(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person:\n            person.archived = True\n            person.published = False\n            audit(db, request, "archive_person", "person", person.id)\n            db.commit()\n    return RedirectResponse("/admin/people", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/merge")\nasync def admin_merge_person(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    target_id = parse_int(form.get("target_person_id"))\n    if not target_id or target_id == person_id:\n        return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n    with SessionLocal() as db:\n        source = db.scalar(\n            select(MissingPerson).options(selectinload(MissingPerson.sources)).where(MissingPerson.id == person_id)\n        )\n        target = db.scalar(\n            select(MissingPerson).options(selectinload(MissingPerson.sources)).where(MissingPerson.id == target_id)\n        )\n        if source is None or target is None or source.disaster_id != target.disaster_id:\n            return HTMLResponse("Invalid merge target", status_code=400)\n\n        target_urls = {item.url for item in target.sources}\n        for source_item in list(source.sources):\n            if source_item.url in target_urls:\n                db.delete(source_item)\n            else:\n                source_item.person_id = target.id\n                target_urls.add(source_item.url)\n\n        db.execute(\n            Submission.__table__.update()\n            .where(Submission.person_id == source.id)\n            .values(person_id=target.id)\n        )\n\n        # Fill only blank canonical fields. The target remains the admin-selected master record.\n        for field in [\n            "name_ne", "age", "gender", "photo_path", "residential_address_private",\n            "last_seen_date", "last_seen_time", "clothing", "identification_details",\n            "public_contact_number", "private_contact_number",\n        ]:\n            if getattr(target, field) in (None, "") and getattr(source, field) not in (None, ""):\n                setattr(target, field, getattr(source, field))\n        if not target.last_seen_location and source.last_seen_location:\n            target.last_seen_location = source.last_seen_location\n\n        source.archived = True\n        source.published = False\n        audit(\n            db,\n            request,\n            "merge_duplicate_person",\n            "person",\n            source.id,\n            f"merged_into={target.id}; target_case={target.case_number}",\n        )\n        db.commit()\n    return RedirectResponse(f"/admin/people/{target_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/source")\nasync def admin_add_source(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    url = canonicalize_url(str(form.get("url") or ""))\n    if not url:\n        return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n    with SessionLocal() as db:\n        if db.get(MissingPerson, person_id) is None:\n            return HTMLResponse("Not found", status_code=404)\n        existing = db.scalar(select(Source).where(Source.person_id == person_id, Source.url == url))\n        if existing is None:\n            source = Source(\n                person_id=person_id,\n                platform=str(form.get("platform") or "facebook").strip(),\n                url=url,\n                source_name=str(form.get("source_name") or "").strip() or None,\n                source_text=str(form.get("source_text") or "").strip() or None,\n            )\n            db.add(source)\n            db.flush()\n            audit(db, request, "add_source", "source", source.id, url)\n            db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.get("/admin/submissions", response_class=HTMLResponse)\ndef admin_submissions(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        submissions = list(\n            db.scalars(\n                select(Submission).where(Submission.status == "pending").order_by(Submission.created_at.desc())\n            ).all()\n        )\n        duplicate_map: dict[int, list[tuple[MissingPerson, float]]] = {}\n        location_match_map: dict[int, bool] = {}\n        disasters_by_id = {d.id: d for d in db.scalars(select(Disaster)).all()}\n        for sub in submissions:\n            disaster = disasters_by_id.get(sub.disaster_id)\n            location_match_map[sub.id] = bool(\n                disaster and affected_location_match(sub.last_seen_location, disaster.affected_locations)\n            )\n            if sub.kind == "missing_report" and sub.name:\n                duplicate_map[sub.id] = find_duplicates(\n                    db,\n                    disaster_id=sub.disaster_id,\n                    name=sub.name,\n                    location=sub.last_seen_location,\n                    age=sub.age,\n                    phone=sub.public_contact_number,\n                )\n        people = list(\n            db.scalars(\n                select(MissingPerson).where(MissingPerson.archived.is_(False)).order_by(MissingPerson.name)\n            ).all()\n        )\n        people_by_disaster: dict[int, list[MissingPerson]] = {}\n        for person in people:\n            people_by_disaster.setdefault(person.disaster_id, []).append(person)\n        return render(\n            request,\n            "admin_submissions.html",\n            submissions=submissions,\n            duplicate_map=duplicate_map,\n            location_match_map=location_match_map,\n            people_by_disaster=people_by_disaster,\n        )\n\n\n@router.post("/admin/submissions/{submission_id}/approve-new")\ndef approve_submission_new(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        if sub is None or sub.status != "pending" or not sub.name:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        disaster = db.get(Disaster, sub.disaster_id)\n        if disaster is None:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        person = MissingPerson(\n            case_number=next_case_number(db, disaster),\n            disaster_id=sub.disaster_id,\n            name=sub.name,\n            name_ne=sub.name_ne,\n            age=sub.age,\n            gender=sub.gender,\n            photo_path=sub.photo_path,\n            residential_address_private=sub.residential_address_private,\n            last_seen_date=sub.last_seen_date,\n            last_seen_time=sub.last_seen_time,\n            last_seen_location=sub.last_seen_location or "Unknown",\n            clothing=sub.clothing,\n            identification_details=sub.identification_details,\n            public_contact_number=sub.public_contact_number,\n            private_contact_number=sub.reporter_phone_private,\n            published=False,\n        )\n        db.add(person)\n        db.flush()\n        sub.person_id = person.id\n        sub.status = "approved"\n        if sub.social_url:\n            db.add(\n                Source(\n                    person_id=person.id,\n                    platform=detect_platform(sub.social_url),\n                    url=sub.social_url,\n                    source_text=sub.notes,\n                )\n            )\n        audit(db, request, "approve_submission_new", "person", person.id, f"submission={sub.id}")\n        db.commit()\n        return RedirectResponse(f"/admin/people/{person.id}", status_code=303)\n\n\n@router.post("/admin/submissions/{submission_id}/attach")\nasync def attach_submission(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    person_id = parse_int(form.get("person_id"))\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        person = db.get(MissingPerson, person_id) if person_id else None\n        if sub is None or person is None:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        if person.disaster_id != sub.disaster_id:\n            return HTMLResponse("Cannot attach a submission to a person from a different disaster", status_code=400)\n        if sub.status != "pending":\n            return RedirectResponse("/admin/submissions", status_code=303)\n\n        updated_fields = apply_submission_to_master(\n            person,\n            sub,\n        )\n\n        if sub.social_url:\n            existing = db.scalar(select(Source).where(Source.person_id == person.id, Source.url == sub.social_url))\n            if existing is None:\n                db.add(\n                    Source(\n                        person_id=person.id,\n                        platform=detect_platform(sub.social_url),\n                        url=sub.social_url,\n                        source_text=sub.notes,\n                    )\n                )\n        sub.person_id = person.id\n        sub.status = "attached"\n        audit(\n            db,\n            request,\n            "attach_submission",\n            "person",\n            person.id,\n            (\n                f"submission={sub.id}; "\n                f"master_fields_updated={\',\'.join(updated_fields) or \'none\'}"\n            ),\n        )\n        db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n\n@router.post(\n    "/admin/submissions/{submission_id}/edit"\n)\nasync def edit_pending_submission(\n    request: Request,\n    submission_id: int,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    with SessionLocal() as db:\n        sub = db.get(\n            Submission,\n            submission_id,\n        )\n\n        if (\n            sub is None\n            or sub.status != "pending"\n        ):\n            return RedirectResponse(\n                "/admin/submissions",\n                status_code=303,\n            )\n\n        name = str(\n            form.get("name")\n            or ""\n        ).strip()\n\n        if (\n            sub.kind == "missing_report"\n            and not name\n        ):\n            return HTMLResponse(\n                "Name is required",\n                status_code=400,\n            )\n\n        sub.name = name or sub.name\n\n        sub.name_ne = (\n            str(\n                form.get("name_ne")\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.age = parse_int(\n            form.get("age")\n        )\n\n        sub.gender = _normalize_gender(form.get("gender"))\n\n        sub.last_seen_date = parse_date(\n            form.get("last_seen_date")\n        )\n\n        sub.last_seen_time = parse_time(\n            form.get("last_seen_time")\n        )\n\n        sub.last_seen_location = (\n            str(\n                form.get(\n                    "last_seen_location"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.clothing = (\n            str(\n                form.get("clothing")\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.identification_details = (\n            str(\n                form.get(\n                    "identification_details"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.public_contact_number = (\n            str(\n                form.get(\n                    "public_contact_number"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        photo_upload = form.get(\n            "photo"\n        )\n\n        if (\n            photo_upload is not None\n            and getattr(\n                photo_upload,\n                "filename",\n                "",\n            )\n        ):\n            try:\n                photo_path = await save_image(\n                    photo_upload,\n                    settings.upload_dir,\n                )\n            except ValueError as exc:\n                return HTMLResponse(\n                    str(exc),\n                    status_code=400,\n                )\n\n            if photo_path:\n                sub.photo_path = photo_path\n\n        audit(\n            db,\n            request,\n            "edit_pending_submission",\n            "submission",\n            sub.id,\n            "admin-reviewed extracted details",\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        "/admin/submissions",\n        status_code=303,\n    )\n\n\n@router.post("/admin/submissions/{submission_id}/reject")\ndef reject_submission(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        if sub:\n            sub.status = "rejected"\n            audit(db, request, "reject_submission", "submission", sub.id)\n            db.commit()\n    return RedirectResponse("/admin/submissions", status_code=303)\n\n\n@router.get("/admin/discovery", response_class=HTMLResponse)\ndef discovery_page(\n    request: Request,\n    disaster_id: int | None = None,\n    platform: str = "facebook",\n    view: str = "review",\n    q: str = "",\n    wide_queries: int | None = None,\n    wide_raw: int | None = None,\n    wide_added: int | None = None,\n    wide_error: int | None = None,\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    allowed_views = {"review", "relevant", "irrelevant", "processed"}\n    view = view.casefold().strip()\n    if view not in allowed_views:\n        view = "review"\n\n    with SessionLocal() as db:\n        disasters = list(\n            db.scalars(\n                select(Disaster).order_by(\n                    Disaster.active.desc(),\n                    Disaster.start_date.desc(),\n                )\n            ).all()\n        )\n        selected = (\n            db.get(Disaster, disaster_id)\n            if disaster_id\n            else next((d for d in disasters if d.active), disasters[0] if disasters else None)\n        )\n\n        queries = (\n            generate_queries(selected, platform=platform)\n            if selected\n            else []\n        )\n\n        wide_provider_status = serper_status()\n        wide_query_plan: list[str] = []\n        published_urls: set[str] = set()\n        queue_counts = {\n            "review": 0,\n            "relevant": 0,\n            "irrelevant": 0,\n            "processed": 0,\n        }\n        candidates: list[DiscoveryCandidate] = []\n\n        if selected:\n            if platform == "facebook":\n                scopes = collect_known_source_scopes(db, selected.id)\n                wide_query_plan = generate_wide_queries(\n                    selected,\n                    source_scopes=scopes,\n                )\n\n            published_urls = set(\n                db.scalars(\n                    select(Source.url)\n                    .join(MissingPerson, Source.person_id == MissingPerson.id)\n                    .where(\n                        MissingPerson.disaster_id == selected.id,\n                        MissingPerson.published.is_(True),\n                        MissingPerson.archived.is_(False),\n                    )\n                ).all()\n            )\n\n            base_conditions = [\n                DiscoveryCandidate.disaster_id == selected.id,\n                DiscoveryCandidate.platform == platform,\n            ]\n\n            status_groups = {\n                "review": ["new", "needs_ai"],\n                "relevant": ["relevant"],\n                "irrelevant": ["irrelevant", "rejected"],\n                "processed": ["reviewed"],\n            }\n\n            for key, statuses in status_groups.items():\n                count_stmt = (\n                    select(func.count(DiscoveryCandidate.id))\n                    .where(*base_conditions)\n                    .where(DiscoveryCandidate.status.in_(statuses))\n                )\n                if key in {"review", "relevant"} and published_urls:\n                    count_stmt = count_stmt.where(\n                        DiscoveryCandidate.url.notin_(published_urls)\n                    )\n                queue_counts[key] = db.scalar(count_stmt) or 0\n\n            stmt = (\n                select(DiscoveryCandidate)\n                .where(*base_conditions)\n                .where(DiscoveryCandidate.status.in_(status_groups[view]))\n                .order_by(DiscoveryCandidate.found_at.desc())\n            )\n\n            if view in {"review", "relevant"} and published_urls:\n                stmt = stmt.where(\n                    DiscoveryCandidate.url.notin_(published_urls)\n                )\n\n            if q.strip():\n                pattern = f"%{q.strip()}%"\n                stmt = stmt.where(\n                    or_(\n                        DiscoveryCandidate.title.ilike(pattern),\n                        DiscoveryCandidate.snippet.ilike(pattern),\n                    )\n                )\n\n            candidates = list(db.scalars(stmt.limit(300)).all())\n\n        base_params = {\n            "disaster_id": selected.id if selected else "",\n            "platform": platform,\n        }\n        queue_links = {\n            key: "/admin/discovery?" + urlencode(\n                {**base_params, "view": key, **({"q": q.strip()} if q.strip() else {})}\n            )\n            for key in allowed_views\n        }\n        clear_search_url = "/admin/discovery?" + urlencode(\n            {**base_params, "view": view}\n        )\n\n        return render(\n            request,\n            "admin_discovery.html",\n            disasters=disasters,\n            selected=selected,\n            platform=platform,\n            view=view,\n            q=q,\n            queue_counts=queue_counts,\n            queue_links=queue_links,\n            clear_search_url=clear_search_url,\n            queries=[(item, google_search_url(item, selected.start_date)) for item in queries] if selected else [],\n            candidates=candidates,\n            bot_message=None,\n            wide_stats=(\n                {"queries": wide_queries, "raw": wide_raw, "added": wide_added}\n                if wide_queries is not None\n                else None\n            ),\n            wide_provider_status=wide_provider_status,\n            wide_query_plan=wide_query_plan,\n            wide_error=bool(wide_error),\n        )\n\n\n@router.post("/admin/discovery/run")\nasync def discovery_run(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    platform = str(form.get("platform") or "facebook")\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id) if disaster_id else None\n        if disaster is None:\n            return RedirectResponse("/admin/discovery", status_code=303)\n        added = discover_candidates(db, disaster, platform=platform)\n        audit(db, request, "run_discovery_bot", "disaster", disaster.id, f"platform={platform}; added={added}")\n        db.commit()\n    return RedirectResponse(f"/admin/discovery?disaster_id={disaster_id}&platform={platform}", status_code=303)\n\n\n\n@router.post("/admin/wide-discovery/run")\nasync def wide_discovery_run(\n    request: Request,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    disaster_id = parse_int(\n        form.get("disaster_id")\n    )\n\n    with SessionLocal() as db:\n        disaster = (\n            db.get(\n                Disaster,\n                disaster_id,\n            )\n            if disaster_id\n            else None\n        )\n\n        if disaster is None:\n            return RedirectResponse(\n                "/admin/discovery",\n                status_code=303,\n            )\n\n        try:\n            stats = run_wide_discovery(\n                db,\n                disaster,\n            )\n        except SearchProviderUnavailable:\n            return RedirectResponse(\n                (\n                    "/admin/discovery"\n                    f"?disaster_id={disaster_id}"\n                    "&platform=facebook"\n                    "&wide_error=1"\n                ),\n                status_code=303,\n            )\n\n        audit(\n            db,\n            request,\n            "run_wide_discovery",\n            "disaster",\n            disaster.id,\n            (\n                f"queries={stats[\'queries\']}; "\n                f"raw={stats[\'raw_results\']}; "\n                f"needs_ai={stats[\'needs_ai\']}"\n            ),\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        (\n            "/admin/discovery"\n            f"?disaster_id={disaster_id}"\n            "&platform=facebook"\n            f"&wide_queries={stats[\'queries\']}"\n            f"&wide_raw={stats[\'raw_results\']}"\n            f"&wide_added={stats[\'needs_ai\']}"\n        ),\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/manual")\nasync def discovery_manual(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    url = canonicalize_url(str(form.get("url") or ""))\n    platform = str(form.get("platform") or "facebook")\n    if not disaster_id or not url:\n        return RedirectResponse("/admin/discovery", status_code=303)\n    with SessionLocal() as db:\n        existing = db.scalar(\n            select(DiscoveryCandidate).where(\n                DiscoveryCandidate.disaster_id == disaster_id, DiscoveryCandidate.url == url\n            )\n        )\n        if existing is None:\n            candidate = DiscoveryCandidate(\n                disaster_id=disaster_id,\n                platform=platform,\n                query="manual-url",\n                url=url,\n                title=str(form.get("title") or "").strip() or None,\n                snippet=str(form.get("snippet") or "").strip() or None,\n            )\n            db.add(candidate)\n            db.flush()\n            audit(db, request, "add_manual_candidate", "discovery_candidate", candidate.id, url)\n            db.commit()\n    return RedirectResponse(f"/admin/discovery?disaster_id={disaster_id}&platform={platform}", status_code=303)\n\n\n@router.post("/admin/discovery/{candidate_id}/status")\nasync def discovery_candidate_status(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    action = str(form.get("status_action") or "").strip().casefold()\n    current_view = str(form.get("view") or "review").strip().casefold()\n    platform = str(form.get("platform") or "facebook").strip()\n    q = str(form.get("q") or "").strip()\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n\n        if action == "relevant":\n            candidate.status = "relevant"\n        elif action == "irrelevant":\n            candidate.status = "irrelevant"\n        elif action == "restore":\n            candidate.status = "needs_ai"\n        elif action == "processed":\n            candidate.status = "reviewed"\n        elif action == "reopen":\n            candidate.status = "relevant"\n        else:\n            return HTMLResponse("Invalid discovery status", status_code=400)\n\n        audit(\n            db,\n            request,\n            "classify_discovery_candidate",\n            "discovery_candidate",\n            candidate.id,\n            f"status={candidate.status}",\n        )\n        db.commit()\n\n        params = {\n            "disaster_id": candidate.disaster_id,\n            "platform": platform,\n            "view": current_view if current_view in {"review", "relevant", "irrelevant", "processed"} else "review",\n        }\n        if q:\n            params["q"] = q\n\n    return RedirectResponse(\n        "/admin/discovery?" + urlencode(params),\n        status_code=303,\n    )\n\n\n@router.get("/admin/discovery/{candidate_id}/public-details")\nasync def discovery_candidate_public_details(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return JSONResponse({"error": "not found"}, status_code=404)\n        disaster = db.get(Disaster, candidate.disaster_id)\n        if disaster is None:\n            return JSONResponse({"error": "unknown disaster"}, status_code=404)\n\n        source_text = ""\n        if candidate.platform == "facebook":\n            source_text = (await discover_public_post_text(candidate.url)) or ""\n\n        evidence_text = source_text or candidate.snippet or ""\n        prefill = extract_candidate_prefill(\n            candidate,\n            disaster,\n            source_text=source_text,\n        )\n        people = extract_candidate_people_names(\n            candidate,\n            source_text=source_text,\n        )\n        multiple_people = candidate_mentions_multiple_people(\n            candidate,\n            source_text=source_text,\n        )\n\n        return JSONResponse(\n            {\n                "text": evidence_text,\n                "full_public_text_available": bool(source_text),\n                "people": people,\n                "multiple_people": multiple_people,\n                "age": prefill.get("age"),\n                "last_seen_location": prefill.get("last_seen_location"),\n                "public_contact_number": prefill.get("public_contact_number"),\n            }\n        )\n\n\n@router.get("/admin/discovery/{candidate_id}/duplicate-check")\ndef discovery_candidate_duplicate_check(\n    request: Request,\n    candidate_id: int,\n    name: str = "",\n    location: str = "",\n    age: int | None = None,\n    phone: str = "",\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return JSONResponse({"error": "not found"}, status_code=404)\n\n        exact = _exact_name_matches(db, candidate.disaster_id, name)\n        fuzzy = find_duplicates(\n            db,\n            disaster_id=candidate.disaster_id,\n            name=name,\n            location=location,\n            age=age,\n            phone=phone,\n        ) if name.strip() else []\n        pending = _pending_name_matches(db, candidate.disaster_id, name)\n\n        fuzzy_map = {person.id: score for person, score in fuzzy}\n        people = []\n        seen_ids: set[int] = set()\n        for person in exact + [person for person, _ in fuzzy]:\n            if person.id in seen_ids:\n                continue\n            seen_ids.add(person.id)\n            has_source = db.scalar(\n                select(Source.id).where(\n                    Source.person_id == person.id,\n                    Source.url == candidate.url,\n                )\n            ) is not None\n            people.append(\n                {\n                    "id": person.id,\n                    "case_number": person.case_number,\n                    "name": person.name,\n                    "age": person.age,\n                    "last_seen_location": person.last_seen_location,\n                    "score": 100.0 if person in exact else fuzzy_map.get(person.id, 0.0),\n                    "exact_name": person in exact,\n                    "source_already_attached": has_source,\n                }\n            )\n\n        return JSONResponse(\n            {\n                "people": people,\n                "pending": [\n                    {"id": item.id, "name": item.name}\n                    for item in pending[:5]\n                ],\n            }\n        )\n\n\n@router.get(\n    "/admin/discovery/{candidate_id}",\n    response_class=HTMLResponse,\n)\nasync def discovery_candidate_review(\n    request: Request,\n    candidate_id: int,\n    created: int | None = None,\n    attached: int | None = None,\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n\n        disaster = db.get(Disaster, candidate.disaster_id)\n        if disaster is None:\n            return HTMLResponse("Unknown disaster", status_code=404)\n\n        source_image_url = None\n        source_post_text = ""\n        ocr_text = ""\n        ocr_detail = None\n\n        if candidate.platform == "facebook":\n            source_post_text = (await discover_public_post_text(candidate.url)) or ""\n            source_image_url = await discover_public_post_image(candidate.url)\n\n        if source_image_url:\n            if ocr_available():\n                ocr_dir = settings.upload_dir / "_ocr_preview"\n                ocr_filename = await download_public_source_image(\n                    source_image_url,\n                    ocr_dir,\n                )\n                if ocr_filename:\n                    local_path = ocr_dir / ocr_filename\n                    result = extract_ocr_text(local_path)\n                    ocr_text = result.text\n                    ocr_detail = result.detail\n                    try:\n                        local_path.unlink(missing_ok=True)\n                        ocr_dir.rmdir()\n                    except OSError:\n                        pass\n            else:\n                ocr_detail = (\n                    "Local OCR is not available yet. Install Tesseract OCR "\n                    "and the Nepali language data to read poster text automatically."\n                )\n\n        prefill = extract_candidate_prefill(\n            candidate,\n            disaster,\n            ocr_text=ocr_text,\n            source_text=source_post_text,\n        )\n        detected_people = extract_candidate_people_names(\n            candidate,\n            source_text=source_post_text,\n            ocr_text=ocr_text,\n        )\n        multiple_people_signal = candidate_mentions_multiple_people(\n            candidate,\n            source_text=source_post_text,\n            ocr_text=ocr_text,\n        )\n        if prefill.get("name") and prefill["name"].casefold() not in {\n            item.casefold() for item in detected_people\n        }:\n            detected_people.insert(0, prefill["name"])\n\n        source_submission_names = {\n            (item or "").strip().casefold()\n            for item in db.scalars(\n                select(Submission.name).where(\n                    Submission.disaster_id == candidate.disaster_id,\n                    Submission.social_url == candidate.url,\n                    Submission.status != "rejected",\n                )\n            ).all()\n            if item\n        }\n        remaining_people = [\n            item for item in detected_people\n            if item.casefold() not in source_submission_names\n        ]\n\n        if (\n            created\n            and remaining_people\n            and str(prefill.get("name") or "").strip().casefold()\n            in source_submission_names\n        ):\n            # After one person is created from a multi-person source, move the\n            # review form to the next explicit name. Other fields remain review\n            # suggestions and must still be checked by the operator.\n            prefill["name"] = remaining_people[0]\n\n        exact_duplicates = _exact_name_matches(\n            db,\n            candidate.disaster_id,\n            str(prefill.get("name") or ""),\n        )\n        pending_duplicates = _pending_name_matches(\n            db,\n            candidate.disaster_id,\n            str(prefill.get("name") or ""),\n        )\n\n        db.commit()\n\n        return render(\n            request,\n            "admin_discovery_review.html",\n            candidate=candidate,\n            prefill=prefill,\n            source_image_url=source_image_url,\n            source_post_text=source_post_text,\n            ocr_text=ocr_text,\n            ocr_detail=ocr_detail,\n            detected_people=detected_people,\n            remaining_people=remaining_people,\n            multiple_people_signal=multiple_people_signal,\n            exact_duplicates=exact_duplicates,\n            pending_duplicates=pending_duplicates,\n            source_submission_names=source_submission_names,\n            created=bool(created),\n            attached=bool(attached),\n        )\n\n\n@router.post("/admin/discovery/{candidate_id}/submission")\nasync def discovery_to_submission(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n        if candidate.status in {"irrelevant", "rejected"}:\n            return HTMLResponse(\n                "Restore this discovery candidate before creating a submission.",\n                status_code=409,\n            )\n\n        name = str(form.get("name") or "").strip()\n        location = str(form.get("last_seen_location") or "").strip()\n        if not name or not location:\n            return RedirectResponse(f"/admin/discovery/{candidate_id}", status_code=303)\n\n        ocr_text = str(form.get("ocr_text") or "").strip()\n        source_post_text = str(form.get("source_post_text") or "").strip()\n        notes_parts = []\n        if source_post_text:\n            notes_parts.append("Public post text:\\n" + source_post_text[:12_000])\n        elif candidate.snippet:\n            notes_parts.append("Search/public snippet:\\n" + candidate.snippet)\n        if ocr_text:\n            notes_parts.append("OCR text from reviewed source image:\\n" + ocr_text)\n        notes = "\\n\\n".join(part.strip() for part in notes_parts if part.strip()) or None\n\n        exact_duplicates = _exact_name_matches(db, candidate.disaster_id, name)\n        duplicate_action = str(form.get("duplicate_action") or "").strip().casefold()\n\n        if exact_duplicates:\n            if duplicate_action.startswith("attach:"):\n                try:\n                    person_id = int(duplicate_action.split(":", 1)[1])\n                except ValueError:\n                    return HTMLResponse("Invalid duplicate action", status_code=400)\n                person = next((item for item in exact_duplicates if item.id == person_id), None)\n                if person is None:\n                    return HTMLResponse("Duplicate target does not match this name", status_code=409)\n\n                existing_source = db.scalar(\n                    select(Source).where(\n                        Source.person_id == person.id,\n                        Source.url == candidate.url,\n                    )\n                )\n                if existing_source is None:\n                    db.add(\n                        Source(\n                            person_id=person.id,\n                            platform=candidate.platform,\n                            url=candidate.url,\n                            source_text=notes,\n                        )\n                    )\n                elif notes and not existing_source.source_text:\n                    existing_source.source_text = notes\n\n                candidate.status = "relevant"\n                audit(\n                    db,\n                    request,\n                    "attach_discovery_source_existing_person",\n                    "person",\n                    person.id,\n                    candidate.url,\n                )\n                db.commit()\n                return RedirectResponse(\n                    f"/admin/discovery/{candidate_id}?attached=1#person-entry-form",\n                    status_code=303,\n                )\n\n            if duplicate_action != "continue":\n                return HTMLResponse(\n                    "Duplicate name detected. Choose the existing person to attach this source, "\n                    "or explicitly confirm that this is a different person with the same name.",\n                    status_code=409,\n                )\n\n        pending_duplicates = _pending_name_matches(\n            db,\n            candidate.disaster_id,\n            name,\n        )\n        if pending_duplicates and duplicate_action != "continue":\n            return HTMLResponse(\n                "A pending submission already uses this name. Review the pending entry first, "\n                "or explicitly confirm that this should be a separate entry.",\n                status_code=409,\n            )\n\n        source_image_url = str(form.get("source_image_url") or "").strip()\n        include_source_image = str(form.get("include_source_image") or "") == "1"\n        photo_path = None\n\n        if include_source_image and source_image_url and is_allowed_public_image_url(source_image_url):\n            photo_path = await download_public_source_image(\n                source_image_url,\n                settings.upload_dir,\n            )\n\n        same_source_submissions = db.scalars(\n            select(Submission).where(\n                Submission.disaster_id == candidate.disaster_id,\n                Submission.social_url == candidate.url,\n                Submission.status != "rejected",\n            )\n        ).all()\n        existing_same_source = any(\n            (item.name or "").strip().casefold() == name.casefold()\n            for item in same_source_submissions\n        )\n        if existing_same_source:\n            return HTMLResponse(\n                "This person already has a submission from this exact public source.",\n                status_code=409,\n            )\n\n        sub = Submission(\n            disaster_id=candidate.disaster_id,\n            kind="missing_report",\n            name=name,\n            photo_path=photo_path,\n            name_ne=str(form.get("name_ne") or "").strip() or None,\n            age=parse_int(form.get("age")),\n            gender=_normalize_gender(form.get("gender")),\n            last_seen_date=parse_date(form.get("last_seen_date")),\n            last_seen_time=parse_time(form.get("last_seen_time")),\n            last_seen_location=location,\n            clothing=str(form.get("clothing") or "").strip() or None,\n            identification_details=str(form.get("identification_details") or "").strip() or None,\n            public_contact_number=str(form.get("public_contact_number") or "").strip() or None,\n            social_url=candidate.url,\n            notes=notes,\n        )\n        db.add(sub)\n\n        # Keep the source in Relevant until an operator explicitly marks the\n        # whole post processed. One post may contain several missing people.\n        candidate.status = "relevant"\n        db.flush()\n        audit(\n            db,\n            request,\n            "candidate_to_submission",\n            "submission",\n            sub.id,\n            candidate.url,\n        )\n        db.commit()\n\n    return RedirectResponse(\n        f"/admin/discovery/{candidate_id}?created=1#person-entry-form",\n        status_code=303,\n    )\n\n\n@router.get(\n    "/admin/ai-review",\n    response_class=HTMLResponse,\n)\ndef discovery_ai_review_page(\n    request: Request,\n    disaster_id: int,\n    platform: str = "facebook",\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        disaster = db.get(\n            Disaster,\n            disaster_id,\n        )\n\n        if disaster is None:\n            return HTMLResponse(\n                "Unknown disaster",\n                status_code=404,\n            )\n\n        candidates = list(\n            db.scalars(\n                select(DiscoveryCandidate)\n                .where(\n                    DiscoveryCandidate.disaster_id\n                    == disaster.id,\n                    DiscoveryCandidate.platform\n                    == platform,\n                    DiscoveryCandidate.status.in_(\n                        ["new", "needs_ai", "relevant"]\n                    ),\n                )\n                .order_by(\n                    DiscoveryCandidate.found_at.desc()\n                )\n                .limit(100)\n            ).all()\n        )\n\n        prompt = build_free_ai_review_prompt(\n            disaster,\n            candidates,\n        )\n\n        return render(\n            request,\n            "admin_ai_review.html",\n            disaster=disaster,\n            platform=platform,\n            candidates=candidates,\n            prompt=prompt,\n        )\n\n\n@router.post(\n    "/admin/ai-review/import"\n)\nasync def discovery_ai_review_import(\n    request: Request,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    disaster_id = parse_int(\n        form.get("disaster_id")\n    )\n\n    platform = str(\n        form.get("platform") or "facebook"\n    ).strip()\n\n    raw_result = str(\n        form.get("result_json") or ""\n    ).strip()\n\n    if not disaster_id or not raw_result:\n        return HTMLResponse(\n            "Missing AI review data",\n            status_code=400,\n        )\n\n    try:\n        results = parse_free_ai_review(\n            raw_result\n        )\n    except ValueError:\n        return HTMLResponse(\n            "Invalid AI review JSON. "\n            "Return to Free AI Review and paste "\n            "the JSON response exactly.",\n            status_code=400,\n        )\n\n    created = 0\n    rejected = 0\n    uncertain = 0\n\n    downloaded_images: dict[str, str | None] = {}\n\n    with SessionLocal() as db:\n        disaster = db.get(\n            Disaster,\n            disaster_id,\n        )\n\n        if disaster is None:\n            return HTMLResponse(\n                "Unknown disaster",\n                status_code=404,\n            )\n\n        for result in results:\n            candidate = db.get(\n                DiscoveryCandidate,\n                result["candidate_id"],\n            )\n\n            # AI output never gets authority to change\n            # disaster/source identity.\n            if candidate is None:\n                continue\n\n            if (\n                candidate.disaster_id\n                != disaster.id\n            ):\n                continue\n\n            if candidate.platform != platform:\n                continue\n\n            if candidate.status not in {\n                "new",\n                "needs_ai",\n                "relevant",\n            }:\n                continue\n\n            decision = result["decision"]\n\n            if decision == "reject":\n                candidate.status = "irrelevant"\n                rejected += 1\n                continue\n\n            if decision == "uncertain":\n                uncertain += 1\n                continue\n\n            accepted_person = False\n\n            for person_data in result["people"]:\n                name = str(\n                    person_data.get("name")\n                    or ""\n                ).strip()\n\n                if not name:\n                    continue\n\n                accepted_person = True\n\n                existing = db.scalar(\n                    select(Submission.id).where(\n                        Submission.disaster_id\n                        == disaster.id,\n                        Submission.social_url\n                        == candidate.url,\n                        Submission.name\n                        == name,\n                    )\n                )\n\n                if existing:\n                    continue\n\n                image_url = str(\n                    person_data.get(\n                        "image_url"\n                    )\n                    or ""\n                ).strip()\n\n                photo_path = None\n\n                if (\n                    image_url\n                    and is_allowed_public_image_url(\n                        image_url\n                    )\n                ):\n                    if (\n                        image_url\n                        not in downloaded_images\n                    ):\n                        downloaded_images[\n                            image_url\n                        ] = (\n                            await download_public_source_image(\n                                image_url,\n                                settings.upload_dir,\n                            )\n                        )\n\n                    photo_path = (\n                        downloaded_images[\n                            image_url\n                        ]\n                    )\n\n                reason = result.get(\n                    "reason"\n                ) or ""\n\n                confidence = result.get(\n                    "confidence"\n                )\n\n                notes = (\n                    candidate.snippet\n                    or ""\n                ).strip()\n\n                ai_note = (\n                    f"Free AI review: {reason}"\n                )\n\n                if confidence is not None:\n                    ai_note += (\n                        f" | confidence={confidence}"\n                    )\n\n                if (\n                    image_url\n                    and is_allowed_public_image_url(\n                        image_url\n                    )\n                ):\n                    ai_note += (\n                        f" | source_image_url={image_url}"\n                    )\n\n                if notes:\n                    notes = (\n                        notes\n                        + "\\n\\n"\n                        + ai_note\n                    )\n                else:\n                    notes = ai_note\n\n                submission = Submission(\n                    disaster_id=disaster.id,\n                    kind="missing_report",\n                    name=name,\n                    photo_path=photo_path,\n                    name_ne=(\n                        str(\n                            person_data.get(\n                                "name_ne"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    age=parse_int(\n                        person_data.get("age")\n                    ),\n                    gender=_normalize_gender(person_data.get("gender")),\n                    last_seen_date=parse_date(\n                        person_data.get(\n                            "last_seen_date"\n                        )\n                    ),\n                    last_seen_time=parse_time(\n                        person_data.get(\n                            "last_seen_time"\n                        )\n                    ),\n                    last_seen_location=(\n                        str(\n                            person_data.get(\n                                "last_seen_location"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    clothing=(\n                        str(\n                            person_data.get(\n                                "clothing"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    identification_details=(\n                        str(\n                            person_data.get(\n                                "identification_details"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    public_contact_number=(\n                        str(\n                            person_data.get(\n                                "public_contact_number"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    social_url=candidate.url,\n                    notes=notes,\n                )\n\n                db.add(submission)\n                created += 1\n\n            if accepted_person:\n                candidate.status = "reviewed"\n\n        audit(\n            db,\n            request,\n            "import_free_ai_review",\n            "disaster",\n            disaster.id,\n            (\n                f"platform={platform}; "\n                f"submissions={created}; "\n                f"rejected={rejected}; "\n                f"uncertain={uncertain}"\n            ),\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        "/admin/submissions",\n        status_code=303,\n    )\n\n\n@router.get("/admin/export", response_class=HTMLResponse)\ndef export_page(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_export.html", disasters=disasters)\n\n\n@router.get("/admin/export/{file_type}")\ndef export_data(request: Request, file_type: str, disaster_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    if file_type not in {"csv", "xlsx"}:\n        return HTMLResponse("Unsupported export", status_code=400)\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id)\n        if disaster is None:\n            return HTMLResponse("Unknown disaster", status_code=404)\n        if file_type == "csv":\n            data = build_csv(db, disaster_id)\n            media = "text/csv; charset=utf-8"\n        else:\n            data = build_xlsx(db, disaster_id)\n            media = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"\n        audit(db, request, "export", "disaster", disaster_id, file_type)\n        db.commit()\n        filename = f"{disaster.code.lower()}-missing-people.{file_type}"\n        return Response(\n            data,\n            media_type=media,\n            headers={"Content-Disposition": f\'attachment; filename="{filename}"\'},\n        )\n\n\n@router.get("/admin/people/{person_id}/share-card")\ndef share_card(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        image = build_share_card(person)\n        audit(db, request, "generate_share_card", "person", person.id)\n        db.commit()\n        return Response(\n            image,\n            media_type="image/png",\n            headers={"Content-Disposition": f\'inline; filename="{person.case_number}.png"\'},\n        )\n', 'app/services/candidate_extract.py': 'from __future__ import annotations\n\nimport re\nfrom datetime import datetime\nfrom typing import Any\n\nfrom ..models import Disaster, DiscoveryCandidate\n\n\nNEPALI_DIGITS = str.maketrans("०१२३४५६७८९", "0123456789")\n\nPHONE_RE = re.compile(\n    r"(?<!\\d)(?:\\+?977[-\\s]?)?(9\\d(?:[\\s-]?\\d){8})(?!\\d)"\n)\n\nAGE_PATTERNS = [\n    re.compile(r"\\bage\\s*[:\\-]?\\s*(\\d{1,3})\\b", re.IGNORECASE),\n    re.compile(r"\\b(\\d{1,3})\\s*years?\\s*old\\b", re.IGNORECASE),\n    re.compile(r"\\b(\\d{1,3})\\s*(?:yrs?|y/o)\\b", re.IGNORECASE),\n    re.compile(r"\\bउमेर\\s*[:\\-]?\\s*(\\d{1,3})\\b"),\n    re.compile(r"\\((\\d{1,3})\\)"),\n]\n\nNAME_PATTERNS = [\n    re.compile(\n        r"\\bPerson\\s+Missing\\s+"\n        r"(?:Mr\\.?|Ms\\.?|Mrs\\.?|Er\\.?)?\\s*"\n        r"([A-Z][A-Za-z\'.-]+(?:\\s+[A-Z][A-Za-z\'.-]+){1,4})",\n        re.IGNORECASE,\n    ),\n    re.compile(\n        r"\\bMissing\\s+Person\\s*[:\\-]?\\s*"\n        r"(?:Mr\\.?|Ms\\.?|Mrs\\.?|Er\\.?)?\\s*"\n        r"([A-Z][A-Za-z\'.-]+(?:\\s+[A-Z][A-Za-z\'.-]+){1,4})",\n        re.IGNORECASE,\n    ),\n    re.compile(\n        r"\\bName\\s*[:\\-]\\s*"\n        r"([A-Z][A-Za-z\'.-]+(?:\\s+[A-Z][A-Za-z\'.-]+){1,4})",\n        re.IGNORECASE,\n    ),\n]\n\nNEPALI_NAME_RE = re.compile(\n    r"(?:नाम|नाम थर)\\s*[:\\-]?\\s*([\\u0900-\\u097F][\\u0900-\\u097F\\s.\'’-]{1,100})"\n)\n\nSTOP_WORDS = {\n    "was", "is", "has", "who", "from", "working", "works", "last",\n    "missing", "person", "people", "out", "contact", "facebook",\n}\n\nDETAIL_KEYWORDS = (\n    "address", "resident", "residence", "home", "work", "works", "working",\n    "workplace", "occupation", "profession", "employee", "engineer", "driver",\n    "guide", "bank", "hydropower", "hotel", "guest house", "family", "father",\n    "mother", "son", "daughter", "brother", "sister", "husband", "wife",\n    "travel", "travelling", "traveling", "route", "vehicle", "bike", "car",\n    "ठेगाना", "बसोबास", "पेशा", "कार्यरत", "काम", "परिवार", "बुबा", "आमा",\n    "छोरा", "छोरी", "दाजु", "भाइ", "दिदी", "बहिनी", "यात्रा", "सवारी",\n)\n\n\ndef _normalize_digits(text: str) -> str:\n    return text.translate(NEPALI_DIGITS)\n\n\ndef _clean_name(value: str) -> str:\n    words = value.strip(" ,-–—.").split()\n    cleaned: list[str] = []\n\n    for word in words:\n        if word.casefold().rstrip(".,") in STOP_WORDS:\n            break\n        cleaned.append(word.strip(" ,-–—."))\n\n    while cleaned and cleaned[0].casefold().rstrip(".") in {"mr", "mrs", "ms", "er"}:\n        cleaned.pop(0)\n\n    return " ".join(cleaned).strip()\n\n\ndef _extract_name(title: str, snippet: str, ocr_text: str = "") -> str | None:\n    # Title is intentionally searched first because search-engine snippets can\n    # sometimes contain text stitched from another post.\n    for source in (title, snippet, ocr_text):\n        if not source:\n            continue\n        for pattern in NAME_PATTERNS:\n            match = pattern.search(source)\n            if match:\n                value = _clean_name(match.group(1))\n                if 2 <= len(value.split()) <= 5:\n                    return value\n\n    for nepali_term in ("सम्पर्कविहीन", "सम्पर्क विहीन", "बेपत्ता", "हराएको"):\n        if nepali_term not in title:\n            continue\n        before = title.split(nepali_term, 1)[0]\n        if " - " in before:\n            before = before.split(" - ")[-1]\n        before = re.sub(\n            r"^(?:Mr|Mrs|Ms|Er)\\.?\\s+",\n            "",\n            before.strip(),\n            flags=re.IGNORECASE,\n        )\n        value = _clean_name(before)\n        if 2 <= len(value.split()) <= 5:\n            return value\n\n    return None\n\n\ndef _extract_nepali_name(text: str) -> str | None:\n    match = NEPALI_NAME_RE.search(text)\n    if not match:\n        return None\n    value = re.split(r"[\\n|,;]", match.group(1), maxsplit=1)[0].strip(" .,:;-–—")\n    words = value.split()\n    if 1 <= len(words) <= 6:\n        return value[:255]\n    return None\n\n\ndef _extract_age(text: str) -> int | None:\n    text = _normalize_digits(text)\n    for pattern in AGE_PATTERNS:\n        match = pattern.search(text)\n        if not match:\n            continue\n        try:\n            age = int(match.group(1))\n        except ValueError:\n            continue\n        if 0 < age < 120:\n            return age\n    return None\n\n\ndef _extract_phones(text: str) -> str | None:\n    text = _normalize_digits(text)\n    found: list[str] = []\n    for match in PHONE_RE.finditer(text):\n        number = re.sub(r"\\D", "", match.group(1))\n        if len(number) == 10 and number not in found:\n            found.append(number)\n        if len(found) >= 3:\n            break\n    return ", ".join(found) if found else None\n\n\ndef _clean_location(value: str) -> str | None:\n    value = re.sub(\n        r"^\\s*(?:at\\s+)?\\d{1,2}(?::\\d{2})?\\s*(?:am|pm)?\\s*(?:in|at)?\\s*",\n        "",\n        value,\n        flags=re.IGNORECASE,\n    )\n    value = re.sub(\n        r"\\s+at\\s+\\d{1,2}(?::\\d{2})?\\s*(?:am|pm)?\\s*$",\n        "",\n        value,\n        flags=re.IGNORECASE,\n    )\n    value = re.split(\n        r"\\b(?:and|who|has|was|is|since|after|before|please|contact)\\b",\n        value,\n        maxsplit=1,\n        flags=re.IGNORECASE,\n    )[0]\n    value = value.strip(" ,.;:-–—")\n    return value[:250] if value else None\n\n\ndef _extract_location(text: str, disaster: Disaster) -> str | None:\n    explicit_patterns = [\n        re.compile(r"\\blast\\s+known\\s+location\\s*[:\\-]?\\s*([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\blast\\s+known\\s+to\\s+be\\s+in\\s+([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\blast\\s+seen(?:\\s+location)?\\s*[:\\-]\\s*([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\blast\\s+seen\\s+(?:at|in)\\s+([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\bmissing\\s+from\\s+([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\blocation\\s*[:\\-]\\s*([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"(?:अन्तिम\\s+पटक\\s+देखिएको\\s+स्थान|हराएको\\s+स्थान|स्थान)\\s*[:\\-]?\\s*([^.;\\n]+)"),\n    ]\n\n    for pattern in explicit_patterns:\n        match = pattern.search(text)\n        if match:\n            value = _clean_location(match.group(1))\n            if value and not re.fullmatch(r"\\d{1,2}(?::\\d{2})?\\s*(?:am|pm)?", value, re.IGNORECASE):\n                return value\n\n    folded = text.casefold()\n    matches = [\n        location\n        for location in disaster.locations()\n        if location.casefold() in folded\n    ]\n    if matches:\n        generic_tokens = {token.casefold() for token in disaster.name.split()}\n        specific = [\n            location\n            for location in matches\n            if location.casefold() not in generic_tokens\n        ]\n        if specific:\n            matches = specific\n        return sorted(matches, key=len, reverse=True)[0]\n\n    workplace = re.search(r"\\bworks?\\s+at\\s+([^.;\\n]+)", text, re.IGNORECASE)\n    if workplace:\n        return _clean_location(workplace.group(1))\n\n    return None\n\n\ndef _extract_gender(text: str) -> str | None:\n    match = re.search(r"\\bgender\\s*[:\\-]\\s*(male|female)\\b", text, re.IGNORECASE)\n    if match:\n        return "Male" if match.group(1).casefold() == "male" else "Female"\n\n    match = re.search(r"(?:लिङ्ग|लिंग)\\s*[:\\-]?\\s*(पुरुष|महिला)\\b", text)\n    if match:\n        return "Male" if match.group(1) == "पुरुष" else "Female"\n\n    return None\n\n\ndef _extract_time(text: str) -> str | None:\n    text = _normalize_digits(text)\n    patterns = [\n        re.compile(\n            r"(?:last\\s+(?:seen|contacted)|time)\\D{0,25}"\n            r"(\\d{1,2})(?::(\\d{2}))?\\s*(am|pm)\\b",\n            re.IGNORECASE,\n        ),\n        re.compile(\n            r"(?:last\\s+(?:seen|contacted)|time)\\D{0,25}"\n            r"([01]?\\d|2[0-3]):([0-5]\\d)\\b",\n            re.IGNORECASE,\n        ),\n        re.compile(r"\\b(\\d{1,2}):(\\d{2})\\s*(am|pm)\\b", re.IGNORECASE),\n    ]\n\n    for pattern in patterns:\n        match = pattern.search(text)\n        if not match:\n            continue\n        groups = match.groups()\n        try:\n            hour = int(groups[0])\n            minute = int(groups[1] or 0)\n        except (TypeError, ValueError):\n            continue\n        ampm = groups[2].casefold() if len(groups) >= 3 and groups[2] else None\n        if ampm:\n            if not 1 <= hour <= 12 or not 0 <= minute <= 59:\n                continue\n            if ampm == "pm" and hour != 12:\n                hour += 12\n            if ampm == "am" and hour == 12:\n                hour = 0\n        elif not (0 <= hour <= 23 and 0 <= minute <= 59):\n            continue\n        return f"{hour:02d}:{minute:02d}"\n\n    return None\n\n\ndef _extract_date(text: str) -> str | None:\n    text = _normalize_digits(text)\n    patterns = [\n        (re.compile(r"\\b(20\\d{2})[-/](\\d{1,2})[-/](\\d{1,2})\\b"), "%Y-%m-%d"),\n        (re.compile(r"\\b(\\d{1,2})[/-](\\d{1,2})[/-](20\\d{2})\\b"), "%d-%m-%Y"),\n    ]\n\n    for pattern, kind in patterns:\n        match = pattern.search(text)\n        if not match:\n            continue\n        try:\n            if kind == "%Y-%m-%d":\n                value = datetime(int(match.group(1)), int(match.group(2)), int(match.group(3)))\n            else:\n                value = datetime(int(match.group(3)), int(match.group(2)), int(match.group(1)))\n        except ValueError:\n            continue\n        return value.date().isoformat()\n\n    month_match = re.search(\n        r"\\b(?:last\\s+(?:seen|contacted)\\s*(?:on|since)?\\s*)?"\n        r"(January|February|March|April|May|June|July|August|September|October|November|December)"\n        r"\\s+(\\d{1,2})(?:st|nd|rd|th)?[,]?\\s+(20\\d{2})\\b",\n        text,\n        re.IGNORECASE,\n    )\n    if month_match:\n        try:\n            value = datetime.strptime(\n                f"{month_match.group(1)} {month_match.group(2)} {month_match.group(3)}",\n                "%B %d %Y",\n            )\n            return value.date().isoformat()\n        except ValueError:\n            pass\n\n    return None\n\n\ndef _extract_clothing(text: str) -> str | None:\n    patterns = [\n        re.compile(r"\\b(?:last\\s+seen\\s+)?wearing\\s+([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"\\bclothing\\s*[:\\-]\\s*([^.;\\n]+)", re.IGNORECASE),\n        re.compile(r"(?:लगाएको\\s+लुगा|पोशाक|लुगा)\\s*[:\\-]?\\s*([^.;\\n]+)"),\n    ]\n    for pattern in patterns:\n        match = pattern.search(text)\n        if match:\n            value = match.group(1).strip(" ,.;:-–—")\n            if value:\n                return value[:1000]\n    return None\n\n\ndef _build_identification_details(snippet: str, source_text: str, ocr_text: str, combined: str) -> str | None:\n    details: list[str] = []\n\n    def has_detail_keyword(piece: str) -> bool:\n        for keyword in DETAIL_KEYWORDS:\n            if keyword.isascii():\n                if re.search(r"\\b" + re.escape(keyword) + r"\\b", piece, re.IGNORECASE):\n                    return True\n            elif keyword in piece:\n                return True\n        return False\n\n    def add(label: str, value: str) -> None:\n        value = " ".join(value.split()).strip()\n        if not value:\n            return\n        entry = f"{label}: {value}"\n        if entry not in details:\n            details.append(entry)\n\n    if snippet.strip():\n        add("Search snippet", snippet[:1800])\n\n    if source_text.strip():\n        add("Public post text", source_text[:5000])\n\n    for piece in re.split(r"[\\n\\r]+|(?<=[.!?])\\s+", combined):\n        if has_detail_keyword(piece):\n            add("Other source detail", piece[:700])\n        if len(details) >= 8:\n            break\n\n    if ocr_text.strip():\n        add("OCR text", ocr_text[:3000])\n\n    return "\\n".join(details) or None\n\n\ndef extract_candidate_prefill(\n    candidate: DiscoveryCandidate,\n    disaster: Disaster,\n    ocr_text: str = "",\n    source_text: str = "",\n) -> dict[str, Any]:\n    """Extract only information explicitly present in public text/OCR.\n\n    OCR reads written text from an image. Nothing is inferred from a person\'s\n    face, appearance, or name.\n    """\n    title = candidate.title or ""\n    snippet = candidate.snippet or ""\n    combined = "\\n".join(\n        part for part in (title, source_text, snippet, ocr_text) if part\n    ).strip()\n    normalized = _normalize_digits(combined)\n\n    name_ne = _extract_nepali_name(normalized)\n    name = _extract_name(title, source_text or snippet, ocr_text)\n    if name is None and name_ne:\n        # The master record requires a name. A written Nepali name is valid\n        # source text, so use it rather than inventing a transliteration.\n        name = name_ne\n\n    return {\n        "name": name,\n        "name_ne": name_ne,\n        "age": _extract_age(normalized),\n        "gender": _extract_gender(normalized),\n        "last_seen_date": _extract_date(normalized),\n        "last_seen_time": _extract_time(normalized),\n        "last_seen_location": _extract_location(normalized, disaster),\n        "clothing": _extract_clothing(normalized),\n        "identification_details": _build_identification_details(\n            snippet,\n            source_text,\n            ocr_text,\n            normalized,\n        ),\n        "public_contact_number": _extract_phones(normalized),\n    }\n\n\n\n_ORG_WORDS = {\n    "news", "update", "hospital", "health", "police", "army", "bank",\n    "travel", "nurse", "foundation", "official", "media", "project",\n    "hydropower", "school", "college", "nepal", "rasuwa", "flood",\n}\n\n\ndef _looks_like_explicit_person_name(value: str) -> bool:\n    value = _clean_name(value)\n    words = value.split()\n    if not (1 <= len(words) <= 5):\n        return False\n    if any(word.casefold().strip(".\'’-") in _ORG_WORDS for word in words):\n        return False\n    if any(word.casefold() in {"their", "his", "her", "sons", "daughters", "family"} for word in words):\n        return False\n    for word in words:\n        cleaned = word.strip(".\'’-")\n        if not cleaned:\n            return False\n        if cleaned[0].isalpha() and not cleaned[0].isupper():\n            return False\n    return True\n\n\ndef extract_candidate_people_names(\n    candidate: DiscoveryCandidate,\n    source_text: str = "",\n    ocr_text: str = "",\n) -> list[str]:\n    """Return explicitly written possible person names from one public source.\n\n    The result is only a review aid. It never identifies anyone from a photo.\n    """\n    title = candidate.title or ""\n    snippet = candidate.snippet or ""\n    sources = [title, source_text, snippet, ocr_text]\n    names: list[str] = []\n    seen: set[str] = set()\n\n    def add(value: str) -> None:\n        value = _clean_name(value)\n        if not _looks_like_explicit_person_name(value):\n            return\n        folded = value.casefold()\n        if folded in seen:\n            return\n        seen.add(folded)\n        names.append(value[:255])\n\n    # Repeated explicit labels, including list-style posts.\n    label_pattern = re.compile(\n        r"(?:Person\\s+Missing|Missing\\s+Person(?:\\s+Name)?|Name)\\s*[:\\-]?\\s*"\n        r"([^\\n.;]{2,180})",\n        re.IGNORECASE,\n    )\n\n    for source in sources:\n        if not source:\n            continue\n        for match in label_pattern.finditer(source):\n            segment = match.group(1)\n            segment = re.split(\n                r"\\b(?:has|have|was|is|from|aged?|age|last|works?|working|location|contact)\\b",\n                segment,\n                maxsplit=1,\n                flags=re.IGNORECASE,\n            )[0]\n            for piece in re.split(r"\\s+(?:and|&)\\s+|[,·•|↪]+", segment):\n                piece = piece.strip(" ,:;-–—")\n                if piece:\n                    add(piece)\n\n    # Capture explicit two-name constructions such as\n    # "Dorje Tamang and Pasang Tamang have been out of contact".\n    pair_pattern = re.compile(\n        r"\\b([A-Z][A-Za-z\'.-]+(?:\\s+[A-Z][A-Za-z\'.-]+){0,3})\\s+and\\s+"\n        r"([A-Z][A-Za-z\'.-]+(?:\\s+[A-Z][A-Za-z\'.-]+){0,3})\\s+"\n        r"(?:has|have|are|were|is|was|missing|out\\s+of\\s+contact)\\b",\n        re.IGNORECASE,\n    )\n    for source in sources:\n        if not source:\n            continue\n        for match in pair_pattern.finditer(source):\n            add(match.group(1))\n            add(match.group(2))\n\n    primary = _extract_name(title, source_text or snippet, ocr_text)\n    if primary:\n        add(primary)\n        primary_folded = primary.casefold()\n        names.sort(key=lambda item: 0 if item.casefold() == primary_folded else 1)\n\n    return names[:12]\n\n_MULTI_PERSON_TERMS = (\n    "missing persons",\n    "missing people",\n    "missing family",\n    "family missing",\n    "and their sons",\n    "and their daughters",\n    "and their children",\n    "and his sons",\n    "and her sons",\n    "and his daughters",\n    "and her daughters",\n    "and family",\n    "parents missing",\n    "couple missing",\n    "husband and wife",\n    "multiple people",\n    "multiple persons",\n    "परिवार",\n    "परिवारका",\n    "व्यक्तिहरू",\n    "बेपत्ता व्यक्तिहरू",\n    "सम्पर्कविहीन व्यक्तिहरू",\n)\n\n\ndef candidate_mentions_multiple_people(\n    candidate: DiscoveryCandidate,\n    source_text: str = "",\n    ocr_text: str = "",\n) -> bool:\n    """Flag explicit public text indicating more than one missing person.\n\n    This is a review hint only. It does not infer identity from any image.\n    """\n    names = extract_candidate_people_names(\n        candidate,\n        source_text=source_text,\n        ocr_text=ocr_text,\n    )\n    if len(names) > 1:\n        return True\n\n    text = "\\n".join(\n        part\n        for part in (\n            candidate.title or "",\n            source_text,\n            candidate.snippet or "",\n            ocr_text,\n        )\n        if part\n    ).casefold()\n\n    return any(term.casefold() in text for term in _MULTI_PERSON_TERMS)\n\n', 'app/services/source_images.py': 'from __future__ import annotations\n\nimport hashlib\nimport uuid\nfrom io import BytesIO\nfrom pathlib import Path\nfrom urllib.parse import urljoin, urlparse\n\nimport httpx\nfrom bs4 import BeautifulSoup\nfrom PIL import Image, UnidentifiedImageError\n\n\nMAX_IMAGE_BYTES = 10 * 1024 * 1024\nMAX_IMAGE_DIMENSION = 2400\n\nALLOWED_CONTENT_TYPES = {\n    "image/jpeg",\n    "image/png",\n    "image/webp",\n}\n\nFORMAT_EXTENSIONS = {\n    "JPEG": ".jpg",\n    "PNG": ".png",\n    "WEBP": ".webp",\n}\n\nImage.MAX_IMAGE_PIXELS = 40_000_000\n\n\ndef is_allowed_public_image_url(url: str) -> bool:\n    """Allow only public HTTPS image hosts used by Meta.\n\n    This prevents the AI JSON from turning the server into\n    an unrestricted URL fetcher.\n    """\n    try:\n        parsed = urlparse(url)\n    except ValueError:\n        return False\n\n    if parsed.scheme.casefold() != "https":\n        return False\n\n    host = (parsed.hostname or "").casefold().rstrip(".")\n\n    if not host:\n        return False\n\n    allowed_exact = {\n        "facebook.com",\n        "www.facebook.com",\n        "instagram.com",\n        "www.instagram.com",\n    }\n\n    allowed_suffixes = (\n        ".facebook.com",\n        ".fbcdn.net",\n        ".fbsbx.com",\n        ".cdninstagram.com",\n        ".instagram.com",\n    )\n\n    return (\n        host in allowed_exact\n        or any(\n            host.endswith(suffix)\n            for suffix in allowed_suffixes\n        )\n    )\n\n\ndef save_public_image_bytes(\n    content: bytes,\n    destination: Path,\n) -> str:\n    if not content:\n        raise ValueError("Empty image")\n\n    if len(content) > MAX_IMAGE_BYTES:\n        raise ValueError("Image exceeds 10 MB")\n\n    try:\n        probe = Image.open(BytesIO(content))\n        image_format = (\n            probe.format or ""\n        ).upper()\n\n        probe.verify()\n\n        if image_format not in FORMAT_EXTENSIONS:\n            raise ValueError(\n                "Unsupported image format"\n            )\n\n        image = Image.open(BytesIO(content))\n\n        image.thumbnail(\n            (\n                MAX_IMAGE_DIMENSION,\n                MAX_IMAGE_DIMENSION,\n            )\n        )\n\n        if (\n            image_format == "JPEG"\n            and image.mode not in {"RGB", "L"}\n        ):\n            image = image.convert("RGB")\n\n        output = BytesIO()\n\n        kwargs = {\n            "optimize": True,\n        }\n\n        if image_format in {\n            "JPEG",\n            "WEBP",\n        }:\n            kwargs["quality"] = 90\n\n        # Re-encoding strips EXIF/GPS metadata.\n        image.save(\n            output,\n            format=image_format,\n            **kwargs,\n        )\n\n        clean = output.getvalue()\n\n    except (\n        UnidentifiedImageError,\n        OSError,\n        ValueError,\n    ) as exc:\n        raise ValueError(\n            "Invalid source image"\n        ) from exc\n\n    digest = hashlib.sha256(\n        clean\n    ).hexdigest()[:16]\n\n    filename = (\n        f"{uuid.uuid4().hex}-"\n        f"{digest}"\n        f"{FORMAT_EXTENSIONS[image_format]}"\n    )\n\n    destination.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    (\n        destination\n        / filename\n    ).write_bytes(clean)\n\n    return filename\n\n\nasync def download_public_source_image(\n    url: str,\n    destination: Path,\n) -> str | None:\n    """Download a direct public Meta image when safely accessible.\n\n    Failure to fetch an image never rejects the underlying\n    missing-person submission.\n    """\n    if not is_allowed_public_image_url(url):\n        return None\n\n    current = url\n\n    timeout = httpx.Timeout(\n        15.0,\n        connect=5.0,\n    )\n\n    headers = {\n        "User-Agent": (\n            "Mozilla/5.0 "\n            "(compatible; MissingPersonHub/1.0)"\n        )\n    }\n\n    try:\n        async with httpx.AsyncClient(\n            timeout=timeout,\n            follow_redirects=False,\n            headers=headers,\n        ) as client:\n\n            for _ in range(4):\n\n                async with client.stream(\n                    "GET",\n                    current,\n                ) as response:\n\n                    if response.status_code in {\n                        301,\n                        302,\n                        303,\n                        307,\n                        308,\n                    }:\n                        location = (\n                            response.headers.get(\n                                "location"\n                            )\n                        )\n\n                        if not location:\n                            return None\n\n                        next_url = urljoin(\n                            current,\n                            location,\n                        )\n\n                        if not is_allowed_public_image_url(\n                            next_url\n                        ):\n                            return None\n\n                        current = next_url\n                        continue\n\n                    if response.status_code != 200:\n                        return None\n\n                    content_type = (\n                        response.headers\n                        .get(\n                            "content-type",\n                            "",\n                        )\n                        .split(\n                            ";",\n                            1,\n                        )[0]\n                        .strip()\n                        .casefold()\n                    )\n\n                    if (\n                        content_type\n                        not in ALLOWED_CONTENT_TYPES\n                    ):\n                        return None\n\n                    chunks: list[bytes] = []\n                    total = 0\n\n                    async for chunk in (\n                        response.aiter_bytes()\n                    ):\n                        total += len(chunk)\n\n                        if total > MAX_IMAGE_BYTES:\n                            return None\n\n                        chunks.append(chunk)\n\n                    return save_public_image_bytes(\n                        b"".join(chunks),\n                        destination,\n                    )\n\n    except (\n        httpx.HTTPError,\n        ValueError,\n        OSError,\n    ):\n        return None\n\n    return None\n\n\n\nMAX_POST_HTML_BYTES = 2 * 1024 * 1024\n\n\ndef is_public_facebook_content_url(\n    url: str,\n) -> bool:\n    """Accept only actual public Facebook content URLs."""\n    try:\n        parsed = urlparse(url)\n    except ValueError:\n        return False\n\n    if parsed.scheme.casefold() != "https":\n        return False\n\n    host = (\n        parsed.hostname\n        or ""\n    ).casefold().rstrip(".")\n\n    facebook_host = (\n        host == "facebook.com"\n        or host.endswith(".facebook.com")\n        or host == "fb.com"\n        or host.endswith(".fb.com")\n    )\n\n    if not facebook_host:\n        return False\n\n    path = parsed.path.casefold()\n\n    return (\n        "/posts/" in path\n        or "permalink.php" in path\n        or "story.php" in path\n        or "/reel/" in path\n        or "/reels/" in path\n        or "/photo/" in path\n        or "/photos/" in path\n        or "/share/p/" in path\n        or "/share/v/" in path\n    )\n\n\ndef extract_public_image_url_from_html(\n    html: str,\n    base_url: str,\n) -> str | None:\n    """Extract a direct public Meta image URL from post metadata."""\n\n    soup = BeautifulSoup(\n        html,\n        "html.parser",\n    )\n\n    candidates: list[str] = []\n\n    for property_name in (\n        "og:image",\n        "og:image:url",\n        "twitter:image",\n        "twitter:image:src",\n    ):\n        tag = soup.find(\n            "meta",\n            attrs={\n                "property": property_name,\n            },\n        )\n\n        if tag is None:\n            tag = soup.find(\n                "meta",\n                attrs={\n                    "name": property_name,\n                },\n            )\n\n        if tag is not None:\n            content = str(\n                tag.get("content")\n                or ""\n            ).strip()\n\n            if content:\n                candidates.append(content)\n\n    image_src = soup.find(\n        "link",\n        attrs={\n            "rel": "image_src",\n        },\n    )\n\n    if image_src is not None:\n        href = str(\n            image_src.get("href")\n            or ""\n        ).strip()\n\n        if href:\n            candidates.append(href)\n\n    for candidate in candidates:\n        absolute = urljoin(\n            base_url,\n            candidate,\n        )\n\n        if is_allowed_public_image_url(\n            absolute\n        ):\n            return absolute\n\n    return None\n\n\nasync def discover_public_post_image(\n    post_url: str,\n) -> str | None:\n    """Best-effort image discovery from a public Facebook post.\n\n    No login, cookie bypass, private-group access or CAPTCHA\n    bypass is attempted.\n    """\n\n    if not is_public_facebook_content_url(\n        post_url\n    ):\n        return None\n\n    current = post_url\n\n    timeout = httpx.Timeout(\n        15.0,\n        connect=5.0,\n    )\n\n    headers = {\n        "User-Agent": (\n            "Mozilla/5.0 "\n            "(compatible; MissingPersonHub/1.0)"\n        )\n    }\n\n    try:\n        async with httpx.AsyncClient(\n            timeout=timeout,\n            follow_redirects=False,\n            headers=headers,\n        ) as client:\n\n            for _ in range(4):\n\n                async with client.stream(\n                    "GET",\n                    current,\n                ) as response:\n\n                    if response.status_code in {\n                        301,\n                        302,\n                        303,\n                        307,\n                        308,\n                    }:\n                        location = (\n                            response.headers.get(\n                                "location"\n                            )\n                        )\n\n                        if not location:\n                            return None\n\n                        next_url = urljoin(\n                            current,\n                            location,\n                        )\n\n                        # Do not follow login/checkpoint redirects.\n                        if not is_public_facebook_content_url(\n                            next_url\n                        ):\n                            return None\n\n                        current = next_url\n                        continue\n\n                    if response.status_code != 200:\n                        return None\n\n                    content_type = (\n                        response.headers\n                        .get(\n                            "content-type",\n                            "",\n                        )\n                        .split(\n                            ";",\n                            1,\n                        )[0]\n                        .strip()\n                        .casefold()\n                    )\n\n                    if content_type not in {\n                        "text/html",\n                        "application/xhtml+xml",\n                    }:\n                        return None\n\n                    chunks: list[bytes] = []\n                    total = 0\n\n                    async for chunk in (\n                        response.aiter_bytes()\n                    ):\n                        total += len(chunk)\n\n                        if (\n                            total\n                            > MAX_POST_HTML_BYTES\n                        ):\n                            return None\n\n                        chunks.append(chunk)\n\n                    html = b"".join(\n                        chunks\n                    ).decode(\n                        "utf-8",\n                        errors="replace",\n                    )\n\n                    return (\n                        extract_public_image_url_from_html(\n                            html,\n                            current,\n                        )\n                    )\n\n    except (\n        httpx.HTTPError,\n        OSError,\n        ValueError,\n    ):\n        return None\n\n    return None\n\n\ndef _clean_public_post_text(value: str) -> str:\n    value = BeautifulSoup(value or "", "html.parser").get_text(" ", strip=True)\n    value = " ".join(value.split())\n    return value.strip()\n\n\ndef extract_public_post_text_from_html(html: str) -> str | None:\n    """Extract the richest public post text exposed in HTML metadata."""\n    soup = BeautifulSoup(html, "html.parser")\n    candidates: list[str] = []\n\n    for key in ("og:description", "twitter:description", "description"):\n        tag = soup.find("meta", attrs={"property": key})\n        if tag is None:\n            tag = soup.find("meta", attrs={"name": key})\n        if tag is not None:\n            value = _clean_public_post_text(str(tag.get("content") or ""))\n            if value:\n                candidates.append(value)\n\n    import json\n\n    def collect_json(value) -> None:\n        if isinstance(value, dict):\n            for key, item in value.items():\n                if key in {"articleBody", "description", "text", "caption"} and isinstance(item, str):\n                    cleaned = _clean_public_post_text(item)\n                    if cleaned:\n                        candidates.append(cleaned)\n                elif isinstance(item, (dict, list)):\n                    collect_json(item)\n        elif isinstance(value, list):\n            for item in value:\n                collect_json(item)\n\n    for script in soup.find_all("script", attrs={"type": "application/ld+json"}):\n        raw = script.string or script.get_text(" ", strip=True)\n        if not raw or len(raw) > 1_000_000:\n            continue\n        try:\n            collect_json(json.loads(raw))\n        except (json.JSONDecodeError, TypeError, ValueError):\n            continue\n\n    filtered: list[str] = []\n    seen: set[str] = set()\n    for candidate in candidates:\n        folded = candidate.casefold()\n        if not candidate:\n            continue\n        if folded in {"facebook", "log into facebook", "log in to facebook"}:\n            continue\n        if "log into facebook" in folded and len(candidate) < 180:\n            continue\n        if folded in seen:\n            continue\n        seen.add(folded)\n        filtered.append(candidate[:12_000])\n\n    return max(filtered, key=len) if filtered else None\n\n\nasync def discover_public_post_text(post_url: str) -> str | None:\n    """Best-effort public Facebook text retrieval with no login or bypass."""\n    if not is_public_facebook_content_url(post_url):\n        return None\n\n    current = post_url\n    timeout = httpx.Timeout(15.0, connect=5.0)\n    headers = {\n        "User-Agent": "Mozilla/5.0 (compatible; MissingPersonHub/1.0)"\n    }\n\n    try:\n        async with httpx.AsyncClient(\n            timeout=timeout,\n            follow_redirects=False,\n            headers=headers,\n        ) as client:\n            for _ in range(4):\n                async with client.stream("GET", current) as response:\n                    if response.status_code in {301, 302, 303, 307, 308}:\n                        location = response.headers.get("location")\n                        if not location:\n                            return None\n                        next_url = urljoin(current, location)\n                        if not is_public_facebook_content_url(next_url):\n                            return None\n                        current = next_url\n                        continue\n\n                    if response.status_code != 200:\n                        return None\n\n                    content_type = (\n                        response.headers.get("content-type", "")\n                        .split(";", 1)[0]\n                        .strip()\n                        .casefold()\n                    )\n                    if content_type not in {"text/html", "application/xhtml+xml"}:\n                        return None\n\n                    chunks: list[bytes] = []\n                    total = 0\n                    async for chunk in response.aiter_bytes():\n                        total += len(chunk)\n                        if total > MAX_POST_HTML_BYTES:\n                            return None\n                        chunks.append(chunk)\n\n                    html = b"".join(chunks).decode("utf-8", errors="replace")\n                    return extract_public_post_text_from_html(html)\n    except (httpx.HTTPError, OSError, ValueError):\n        return None\n\n    return None\n', 'app/templates/admin_discovery.html': '{% extends "base.html" %}\n{% block content %}\n\n<h1>Public Social Discovery</h1>\n\n<p class="muted">\n  V0 searches public web indexes only. It never logs into Facebook or accesses\n  closed/private groups. Every result remains subject to admin review.\n</p>\n\n<form method="get" class="card inline">\n  <div>\n    <label>Event</label>\n    <select name="disaster_id">\n      {% for d in disasters %}\n      <option value="{{ d.id }}" {% if selected and selected.id == d.id %}selected{% endif %}>\n        {{ d.name }}\n      </option>\n      {% endfor %}\n    </select>\n  </div>\n\n  <div>\n    <label>Platform</label>\n    <select name="platform">\n      {% for p in [\'facebook\',\'web\',\'instagram\',\'tiktok\',\'x\',\'reddit\'] %}\n      <option value="{{ p }}" {% if platform == p %}selected{% endif %}>{{ p }}</option>\n      {% endfor %}\n    </select>\n  </div>\n\n  <input type="hidden" name="view" value="{{ view }}">\n\n  <div>\n    <button>Load Discovery</button>\n  </div>\n</form>\n\n{% if selected %}\n\n{% if wide_error %}\n<div class="notice">\n  <strong>Wide Discovery could not run.</strong><br>\n  The configured Serper / Google Search provider is unavailable, rejected, or\n  has reached its quota.\n</div>\n{% endif %}\n\n{% if wide_stats %}\n<div class="notice">\n  <strong>Wide Discovery finished</strong><br>\n  Queries searched: {{ wide_stats.queries }}<br>\n  Raw search results: {{ wide_stats.raw }}<br>\n  New candidates sent to review: {{ wide_stats.added }}\n</div>\n{% endif %}\n\n<div class="card">\n  <h2>Findings queue</h2>\n  <p class="muted">\n    Relevant and irrelevant decisions are retained. Nothing is deleted, so an\n    administrator can restore a result later if it was classified incorrectly.\n  </p>\n\n  <div class="inline" style="gap:8px; flex-wrap:wrap">\n    <a href="{{ queue_links.review }}">To Review ({{ queue_counts.review }})</a>\n    <a href="{{ queue_links.relevant }}">Relevant ({{ queue_counts.relevant }})</a>\n    <a href="{{ queue_links.irrelevant }}">Irrelevant ({{ queue_counts.irrelevant }})</a>\n    <a href="{{ queue_links.processed }}">Processed ({{ queue_counts.processed }})</a>\n  </div>\n</div>\n\n<form method="get" class="card inline">\n  <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n  <input type="hidden" name="platform" value="{{ platform }}">\n  <input type="hidden" name="view" value="{{ view }}">\n\n  <div style="min-width:320px; flex:1">\n    <label>Search findings by person name</label>\n    <input\n      name="q"\n      value="{{ q }}"\n      placeholder="Name in English or Nepali"\n      autocomplete="off"\n    >\n  </div>\n\n  <div>\n    <button>Search Findings</button>\n  </div>\n\n  {% if q %}\n  <div>\n    <a href="{{ clear_search_url }}">Clear search</a>\n  </div>\n  {% endif %}\n</form>\n\n<div class="grid">\n  <div class="card">\n    <h2>Automated Discovery</h2>\n    <p>Runs the bounded public-web discovery collector and person-level filters.</p>\n    <form method="post" action="/admin/discovery/run">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <input type="hidden" name="platform" value="{{ platform }}">\n      <button>Run Discovery Bot</button>\n    </form>\n  </div>\n\n  {% if platform == \'facebook\' %}\n  <div class="card">\n    <h2>Wide Discovery</h2>\n    <p>\n      Person-focused Facebook discovery using affected places, stronger\n      missing-person phrases, the event date window, and human-confirmed\n      productive sources.\n    </p>\n\n    <p>\n      <strong>Provider:</strong> {{ wide_provider_status.name }} —\n      {% if wide_provider_status.available %}\n        <span class="badge">READY</span>\n      {% else %}\n        <span class="badge">NOT CONFIGURED</span>\n      {% endif %}\n    </p>\n\n    <p class="muted">{{ wide_provider_status.detail }}</p>\n\n    {% if wide_provider_status.available %}\n    <form method="post" action="/admin/wide-discovery/run">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <button>Run Wide Discovery</button>\n    </form>\n    {% else %}\n    <button disabled>Run Wide Discovery</button>\n    <p class="muted">Set SERPER_API_KEY in the server environment to enable it.</p>\n    {% endif %}\n\n    <p class="muted">\n      A run uses at most 40 search queries. Avoid repeating it unnecessarily.\n    </p>\n\n    <details style="margin-top:12px">\n      <summary>Show Wide Search Plan ({{ wide_query_plan|length }} queries)</summary>\n      <div style="max-height:420px; overflow:auto; margin-top:10px">\n        {% for query in wide_query_plan %}\n        <p><strong>{{ \'%03d\'|format(loop.index) }}.</strong> <code>{{ query }}</code></p>\n        {% else %}\n        <p>No wide queries generated.</p>\n        {% endfor %}\n      </div>\n    </details>\n  </div>\n  {% endif %}\n\n  <div class="card">\n    <h2>Free AI Review</h2>\n    <p>\n      Review collected candidates using a free interactive AI session. No AI\n      API call is made.\n    </p>\n    <form method="get" action="/admin/ai-review">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <input type="hidden" name="platform" value="{{ platform }}">\n      <button>Prepare Free AI Review</button>\n    </form>\n  </div>\n\n  <div class="card">\n    <h2>Manual URL Intake</h2>\n    <form method="post" action="/admin/discovery/manual">\n      <input type="hidden" name="disaster_id" value="{{ selected.id }}">\n      <input type="hidden" name="platform" value="{{ platform }}">\n      <label>Public source URL</label>\n      <input type="url" name="url" required>\n      <label>Title</label>\n      <input name="title">\n      <label>Snippet/note</label>\n      <textarea name="snippet"></textarea>\n      <button>Add Candidate</button>\n    </form>\n  </div>\n</div>\n\n<details style="margin-top:18px">\n  <summary>Targeted manual searches</summary>\n  <div class="card">\n    {% for query, url in queries %}\n    <p>\n      <a href="{{ url }}" target="_blank" rel="noopener noreferrer">Search</a>\n      — <code>{{ query }}</code>\n    </p>\n    {% else %}\n    <p>No queries.</p>\n    {% endfor %}\n  </div>\n</details>\n\n<h2>\n  {% if view == \'review\' %}To Review{% elif view == \'relevant\' %}Relevant Findings{% elif view == \'irrelevant\' %}Irrelevant Archive{% else %}Processed Findings{% endif %}\n</h2>\n\n<table>\n  <thead>\n    <tr>\n      <th>Platform</th>\n      <th>Candidate</th>\n      <th>Status</th>\n      <th>Review</th>\n      <th>Classification</th>\n    </tr>\n  </thead>\n  <tbody>\n    {% for c in candidates %}\n    <tr id="candidate-{{ c.id }}">\n      <td>{{ c.platform }}</td>\n      <td>\n        <a href="{{ c.url }}" target="_blank" rel="noopener noreferrer">\n          {{ c.title or c.url }}\n        </a>\n\n        <div\n          class="candidate-public-details"\n          data-candidate-id="{{ c.id }}"\n          style="margin-top:10px"\n        >\n          <div class="muted" style="white-space:pre-wrap">\n            <strong>Search/public text:</strong>\n            <span class="candidate-text">{{ c.snippet or \'No text supplied by search provider.\' }}</span>\n          </div>\n          <div class="candidate-structured" style="margin-top:8px"></div>\n          {% if c.platform == \'facebook\' %}\n          <div class="candidate-load-status muted" style="margin-top:6px">\n            Loading richer public post details when available…\n          </div>\n          {% endif %}\n        </div>\n      </td>\n      <td>{{ c.status }}</td>\n      <td><a class="discovery-review-link" href="/admin/discovery/{{ c.id }}">Review Details</a></td>\n      <td>\n        {% if c.status in [\'new\', \'needs_ai\'] %}\n        <form class="discovery-status-form" method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="relevant">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button>✓ Relevant</button>\n        </form>\n        <form class="discovery-status-form" method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="irrelevant">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button class="secondary">Not relevant</button>\n        </form>\n        {% elif c.status == \'relevant\' %}\n        <form class="discovery-status-form" method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="irrelevant">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button class="secondary">Move to Irrelevant</button>\n        </form>\n        {% elif c.status in [\'irrelevant\', \'rejected\'] %}\n        <form class="discovery-status-form" method="post" action="/admin/discovery/{{ c.id }}/status" style="display:inline">\n          <input type="hidden" name="status_action" value="restore">\n          <input type="hidden" name="platform" value="{{ platform }}">\n          <input type="hidden" name="view" value="{{ view }}">\n          <input type="hidden" name="q" value="{{ q }}">\n          <button>Restore to Review</button>\n        </form>\n        {% else %}\n        <span class="muted">Already processed</span>\n        {% endif %}\n      </td>\n    </tr>\n    {% else %}\n    <tr>\n      <td colspan="5">No findings in this section.</td>\n    </tr>\n    {% endfor %}\n  </tbody>\n</table>\n\n{% endif %}\n\n<script>\n(function () {\n  const blocks = Array.from(document.querySelectorAll(\'.candidate-public-details\'));\n  const scrollKey = `mp-discovery-scroll:${location.pathname}${location.search}`;\n\n  const savedScroll = sessionStorage.getItem(scrollKey);\n  if (savedScroll !== null) {\n    sessionStorage.removeItem(scrollKey);\n    const y = Number(savedScroll);\n    if (Number.isFinite(y)) {\n      requestAnimationFrame(() => window.scrollTo(0, y));\n    }\n  }\n\n  function rememberDiscoveryPosition() {\n    sessionStorage.setItem(scrollKey, String(window.scrollY));\n  }\n\n  document.querySelectorAll(\'.discovery-status-form\').forEach((form) => {\n    form.addEventListener(\'submit\', rememberDiscoveryPosition);\n  });\n\n  document.querySelectorAll(\'.discovery-review-link\').forEach((link) => {\n    link.addEventListener(\'click\', rememberDiscoveryPosition);\n  });\n\n  async function loadDetails(block) {\n    if (block.dataset.loaded === \'1\') return;\n    block.dataset.loaded = \'1\';\n\n    const id = block.dataset.candidateId;\n    const status = block.querySelector(\'.candidate-load-status\');\n    if (!status) return;\n\n    try {\n      const response = await fetch(`/admin/discovery/${id}/public-details`, {\n        credentials: \'same-origin\'\n      });\n      if (!response.ok) throw new Error(\'details unavailable\');\n      const data = await response.json();\n\n      const text = block.querySelector(\'.candidate-text\');\n      if (data.text && text) text.textContent = data.text;\n\n      const structured = block.querySelector(\'.candidate-structured\');\n      const parts = [];\n      if (data.multiple_people) {\n        parts.push(\'<strong>⚠ Multiple people may be reported in this post</strong>\');\n      }\n      if (Array.isArray(data.people) && data.people.length) {\n        parts.push(`<strong>Possible person(s):</strong> ${data.people.map(escapeHtml).join(\', \')}`);\n      }\n      if (data.age) parts.push(`<strong>Age:</strong> ${escapeHtml(String(data.age))}`);\n      if (data.last_seen_location) {\n        parts.push(`<strong>Last seen:</strong> ${escapeHtml(data.last_seen_location)}`);\n      }\n      if (data.public_contact_number) {\n        parts.push(`<strong>Public contact:</strong> ${escapeHtml(data.public_contact_number)}`);\n      }\n      structured.innerHTML = parts.join(\' &nbsp; | &nbsp; \');\n\n      status.textContent = data.full_public_text_available\n        ? \'Fuller public post text loaded into this page.\'\n        : \'Facebook did not expose fuller public text. Showing the best indexed text available.\';\n    } catch (error) {\n      status.textContent = \'Could not load more public text. Showing the indexed search text.\';\n    }\n  }\n\n  function escapeHtml(value) {\n    const div = document.createElement(\'div\');\n    div.textContent = value == null ? \'\' : String(value);\n    return div.innerHTML;\n  }\n\n  if (\'IntersectionObserver\' in window) {\n    const observer = new IntersectionObserver((entries) => {\n      for (const entry of entries) {\n        if (entry.isIntersecting) {\n          loadDetails(entry.target);\n          observer.unobserve(entry.target);\n        }\n      }\n    }, {rootMargin: \'250px\'});\n    blocks.forEach((block) => observer.observe(block));\n  } else {\n    blocks.forEach(loadDetails);\n  }\n})();\n</script>\n\n{% endblock %}\n', 'app/templates/admin_discovery_review.html': '{% extends "base.html" %}\n{% block content %}\n\n<h1>Review Discovery Candidate</h1>\n\n{% if created %}\n<div class="card" style="border:2px solid #2f855a">\n  <strong>Pending entry created.</strong>\n  This post remains in Relevant until you confirm that every missing person in the post has been handled.\n</div>\n{% endif %}\n\n{% if attached %}\n<div class="card" style="border:2px solid #2f855a">\n  <strong>Source attached to the existing person.</strong>\n  No duplicate missing-person entry was created.\n</div>\n{% endif %}\n\n<div class="card">\n  <p>\n    <span class="badge">{{ candidate.platform }}</span>\n    <span class="badge">{{ candidate.status }}</span>\n    <a href="{{ candidate.url }}" target="_blank" rel="noopener noreferrer">\n      Open original public post\n    </a>\n  </p>\n\n  <h2>{{ candidate.title or \'Untitled result\' }}</h2>\n\n  <h3>Public post content available to the system</h3>\n  {% if source_post_text %}\n  <pre class="wrap">{{ source_post_text }}</pre>\n  <p class="muted">\n    Retrieved from public post metadata without logging in. Facebook may still withhold or truncate some content.\n  </p>\n  {% else %}\n  <pre class="wrap">{{ candidate.snippet or \'\' }}</pre>\n  <p class="muted">\n    Facebook did not expose fuller public text, so this is the best indexed text available to the system.\n  </p>\n  {% endif %}\n\n  {% if candidate.status in [\'new\', \'needs_ai\'] %}\n  <div class="inline" style="margin-top:12px">\n    <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n      <input type="hidden" name="status_action" value="relevant">\n      <input type="hidden" name="platform" value="{{ candidate.platform }}">\n      <input type="hidden" name="view" value="review">\n      <button>✓ Mark Relevant</button>\n    </form>\n    <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n      <input type="hidden" name="status_action" value="irrelevant">\n      <input type="hidden" name="platform" value="{{ candidate.platform }}">\n      <input type="hidden" name="view" value="review">\n      <button class="secondary">Mark Irrelevant</button>\n    </form>\n  </div>\n  {% elif candidate.status in [\'irrelevant\', \'rejected\'] %}\n  <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n    <input type="hidden" name="status_action" value="restore">\n    <input type="hidden" name="platform" value="{{ candidate.platform }}">\n    <input type="hidden" name="view" value="irrelevant">\n    <button>Restore to Review</button>\n  </form>\n  {% elif candidate.status == \'reviewed\' %}\n  <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n    <input type="hidden" name="status_action" value="reopen">\n    <input type="hidden" name="platform" value="{{ candidate.platform }}">\n    <input type="hidden" name="view" value="processed">\n    <button>Reopen This Post</button>\n  </form>\n  {% endif %}\n</div>\n\n{% if multiple_people_signal %}\n<div class="card" style="border:2px solid #b7791f">\n  <h2>⚠ Possible multiple missing people in this post</h2>\n  <p>\n    The public text indicates that this source may report more than one missing person.\n    {% if detected_people|length > 1 %}\n      The system found <strong>{{ detected_people|length }}</strong> explicit names.\n    {% endif %}\n    Treat these as review suggestions, not automatic identity decisions.\n  </p>\n  {% if detected_people %}\n  <ul>\n    {% for person_name in detected_people %}\n    <li>\n      {{ person_name }}\n      {% if person_name.casefold() in source_submission_names %}\n        <span class="badge">entry already created from this post</span>\n      {% endif %}\n    </li>\n    {% endfor %}\n  </ul>\n  {% else %}\n  <p class="muted">\n    The post uses plural/family wording, but the system could not safely separate every person\'s name.\n    Review the public text and source image for additional explicitly named people.\n  </p>\n  {% endif %}\n\n  {% if remaining_people %}\n  <p><strong>Still to review from this source:</strong> {{ remaining_people|join(\', \') }}</p>\n  {% else %}\n  <p><strong>All detected names already have an entry from this source.</strong></p>\n  {% endif %}\n</div>\n{% endif %}\n\n{% if source_image_url %}\n<div class="card">\n  <h2>Picture found in public source</h2>\n  <img\n    src="{{ source_image_url }}"\n    alt="Image attached to the public missing-person post"\n    style="max-width:520px; max-height:520px; object-fit:contain; border-radius:8px"\n  >\n  <p class="muted">\n    Source evidence only. OCR may read written text from this image, but the system does not identify a person from their face or infer identity from appearance.\n  </p>\n</div>\n{% endif %}\n\n{% if ocr_text or ocr_detail %}\n<div class="card">\n  <h2>Text detected in source image</h2>\n  {% if ocr_detail %}<p class="muted">{{ ocr_detail }}</p>{% endif %}\n  {% if ocr_text %}\n  <pre class="wrap">{{ ocr_text }}</pre>\n  {% else %}\n  <p>No OCR text was detected.</p>\n  {% endif %}\n</div>\n{% endif %}\n\n<form method="post" action="/admin/discovery/{{ candidate.id }}/submission" class="card" id="person-entry-form">\n  <h2>Create or attach missing-person record</h2>\n  <p class="muted">\n    Review every field. If the same name already exists, the system will warn you and let you attach this new source link instead of creating a duplicate person.\n  </p>\n\n  {% if source_post_text %}\n  <textarea name="source_post_text" style="display:none">{{ source_post_text }}</textarea>\n  {% endif %}\n  {% if ocr_text %}\n  <textarea name="ocr_text" style="display:none">{{ ocr_text }}</textarea>\n  {% endif %}\n\n  {% if multiple_people_signal and remaining_people %}\n  <label>Choose a detected person from this post</label>\n  <select id="detected-person-picker">\n    <option value="">Select a name or type manually below</option>\n    {% for person_name in remaining_people %}\n    <option value="{{ person_name }}">{{ person_name }}</option>\n    {% endfor %}\n  </select>\n  <p class="muted">Selecting a name changes only the Name field. Re-check age, location, contact and all other details for that specific person.</p>\n  {% endif %}\n\n  <div class="inline">\n    <div>\n      <label>Name *</label>\n      <input id="person-name" name="name" value="{{ prefill.name or \'\' }}" required>\n    </div>\n    <div>\n      <label>Nepali name</label>\n      <input name="name_ne" value="{{ prefill.name_ne or \'\' }}">\n    </div>\n    <div>\n      <label>Age</label>\n      <input id="person-age" type="number" name="age" value="{{ prefill.age or \'\' }}">\n    </div>\n  </div>\n\n  <div\n    id="duplicate-warning"\n    class="card"\n    style="{% if exact_duplicates or pending_duplicates %}display:block;{% else %}display:none;{% endif %} border:2px solid #c05621; margin-top:12px"\n  >\n    {% if exact_duplicates %}\n      <h3>⚠ Possible duplicate person</h3>\n      <p>\n        <strong>The same name already exists in this disaster.</strong>\n        If this is another public link for the same person, attach the source instead of creating a duplicate person.\n      </p>\n      {% for item in exact_duplicates %}\n      <label style="display:block; margin:8px 0">\n        <input type="radio" name="duplicate_action" value="attach:{{ item.id }}" required>\n        Attach this source to {{ item.case_number }} — {{ item.name }}\n        {% if item.last_seen_location %} — {{ item.last_seen_location }}{% endif %}\n      </label>\n      {% endfor %}\n      <label style="display:block; margin:8px 0">\n        <input type="radio" name="duplicate_action" value="continue" required>\n        This is a different person with the same name. Continue with a separate pending entry.\n      </label>\n    {% elif pending_duplicates %}\n      <h3>⚠ Pending duplicate-name warning</h3>\n      <p>\n        A pending submission already uses this name. Check Pending Submissions before making another record.\n      </p>\n      <ul>\n        {% for item in pending_duplicates %}\n        <li>Submission #{{ item.id }} — {{ item.name }}</li>\n        {% endfor %}\n      </ul>\n      <label style="display:block; margin:8px 0">\n        <input type="radio" name="duplicate_action" value="continue" required>\n        I reviewed the pending match and still want a separate pending entry.\n      </label>\n    {% endif %}\n  </div>\n\n  <div class="inline">\n    <div>\n      <label>Gender</label>\n      <select name="gender">\n        <option value="" {% if not prefill.gender %}selected{% endif %}>Unknown</option>\n        <option value="Male" {% if prefill.gender == \'Male\' %}selected{% endif %}>Male</option>\n        <option value="Female" {% if prefill.gender == \'Female\' %}selected{% endif %}>Female</option>\n      </select>\n    </div>\n    <div>\n      <label>Last-seen date</label>\n      <input type="date" name="last_seen_date" value="{{ prefill.last_seen_date or \'\' }}">\n    </div>\n    <div>\n      <label>Last-seen time</label>\n      <input type="time" name="last_seen_time" value="{{ prefill.last_seen_time or \'\' }}">\n    </div>\n  </div>\n\n  <label>Last-seen / affected location *</label>\n  <input id="person-location" name="last_seen_location" value="{{ prefill.last_seen_location or \'\' }}" required>\n\n  <label>Clothing</label>\n  <textarea name="clothing">{{ prefill.clothing or \'\' }}</textarea>\n\n  <label>Identification / source details</label>\n  <textarea name="identification_details" rows="10">{{ prefill.identification_details or \'\' }}</textarea>\n\n  <label>Public information contact</label>\n  <input id="person-phone" name="public_contact_number" value="{{ prefill.public_contact_number or \'\' }}">\n\n  {% if source_image_url %}\n  <input type="hidden" name="source_image_url" value="{{ source_image_url }}">\n  <p>\n    <label>\n      <input type="checkbox" name="include_source_image" value="1" checked>\n      Include this reviewed source image in the pending missing-person record\n    </label>\n  </p>\n  {% endif %}\n\n  {% if candidate.status not in [\'irrelevant\', \'rejected\'] %}\n  <button id="create-entry-button">Create Pending Entry</button>\n  {% else %}\n  <p class="muted">Restore this candidate to review before creating a submission.</p>\n  {% endif %}\n</form>\n\n{% if candidate.status not in [\'irrelevant\', \'rejected\', \'reviewed\'] %}\n<div class="card">\n  <h2>Finished reviewing this post?</h2>\n  <p>\n    Only mark the post processed after every missing person mentioned in it has either been entered, attached to an existing person, or intentionally skipped after review.\n  </p>\n  <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n    <input type="hidden" name="status_action" value="processed">\n    <input type="hidden" name="platform" value="{{ candidate.platform }}">\n    <input type="hidden" name="view" value="relevant">\n    <button>✓ Mark Whole Post Processed</button>\n  </form>\n</div>\n{% endif %}\n\n<p class="muted">\n  The system reads only public text and written text detected in source images. It does not use facial recognition or infer identity from appearance.\n</p>\n\n<script>\n(function () {\n  const nameInput = document.getElementById(\'person-name\');\n  const ageInput = document.getElementById(\'person-age\');\n  const locationInput = document.getElementById(\'person-location\');\n  const phoneInput = document.getElementById(\'person-phone\');\n  const warning = document.getElementById(\'duplicate-warning\');\n  const picker = document.getElementById(\'detected-person-picker\');\n  let timer = null;\n\n  function escapeHtml(value) {\n    const div = document.createElement(\'div\');\n    div.textContent = value == null ? \'\' : String(value);\n    return div.innerHTML;\n  }\n\n  async function checkDuplicates() {\n    const name = nameInput.value.trim();\n    if (!name) {\n      warning.style.display = \'none\';\n      warning.innerHTML = \'\';\n      return;\n    }\n\n    const params = new URLSearchParams({\n      name,\n      location: locationInput.value || \'\',\n      phone: phoneInput.value || \'\'\n    });\n    if (ageInput.value) params.set(\'age\', ageInput.value);\n\n    try {\n      const response = await fetch(\n        `/admin/discovery/{{ candidate.id }}/duplicate-check?${params.toString()}`,\n        {credentials: \'same-origin\'}\n      );\n      if (!response.ok) return;\n      const data = await response.json();\n      const exact = (data.people || []).filter((item) => item.exact_name);\n      const similar = (data.people || []).filter((item) => !item.exact_name && item.score >= 70);\n\n      if (!exact.length && !similar.length && !(data.pending || []).length) {\n        warning.style.display = \'none\';\n        warning.innerHTML = \'\';\n        return;\n      }\n\n      let html = \'<h3>⚠ Possible duplicate person</h3>\';\n      if (exact.length) {\n        html += \'<p><strong>The same name already exists in this disaster.</strong> If this is another link for the same person, attach the source instead of creating another person.</p>\';\n        for (const item of exact) {\n          html += `<label style="display:block; margin:8px 0"><input type="radio" name="duplicate_action" value="attach:${item.id}" required> Attach this source to ${escapeHtml(item.case_number)} — ${escapeHtml(item.name)}${item.last_seen_location ? \' — \' + escapeHtml(item.last_seen_location) : \'\'}${item.source_already_attached ? \' (source already attached)\' : \'\'}</label>`;\n        }\n        html += \'<label style="display:block; margin:8px 0"><input type="radio" name="duplicate_action" value="continue" required> This is a different person with the same name. Continue with a separate pending entry.</label>\';\n      }\n      if (similar.length) {\n        html += \'<p><strong>Similar existing cases:</strong></p><ul>\';\n        for (const item of similar) {\n          html += `<li>${escapeHtml(item.case_number)} — ${escapeHtml(item.name)} — match ${escapeHtml(item.score)}%</li>`;\n        }\n        html += \'</ul>\';\n      }\n      if ((data.pending || []).length) {\n        html += \'<p><strong>Pending submissions with this name also exist.</strong> Check them before creating another entry.</p>\';\n        if (!exact.length) {\n          html += \'<label style="display:block; margin:8px 0"><input type="radio" name="duplicate_action" value="continue" required> I reviewed the pending match and still want a separate pending entry.</label>\';\n        }\n      }\n\n      warning.innerHTML = html;\n      warning.style.display = \'block\';\n    } catch (error) {\n      // Duplicate check is advisory in the UI; the server still enforces exact matches.\n    }\n  }\n\n  function scheduleCheck() {\n    clearTimeout(timer);\n    timer = setTimeout(checkDuplicates, 250);\n  }\n\n  [nameInput, ageInput, locationInput, phoneInput].forEach((element) => {\n    if (element) element.addEventListener(\'input\', scheduleCheck);\n  });\n\n  if (picker) {\n    picker.addEventListener(\'change\', function () {\n      if (this.value) {\n        nameInput.value = this.value;\n        scheduleCheck();\n      }\n    });\n  }\n\n  checkDuplicates();\n})();\n</script>\n\n{% endblock %}\n', 'tests/test_discovery_review_intelligence_upgrade.py': 'from datetime import date\n\nfrom app.models import Disaster, DiscoveryCandidate\nfrom app.services.candidate_extract import (\n    candidate_mentions_multiple_people,\n    extract_candidate_people_names,\n    extract_candidate_prefill,\n)\nfrom app.services.source_images import extract_public_post_text_from_html\n\n\ndef disaster():\n    return Disaster(\n        code="RF",\n        name="Rasuwa Flood",\n        disaster_type="flood",\n        start_date=date(2026, 8, 26),\n        affected_locations="Rasuwa\\nTimure\\nBetrawati",\n    )\n\n\ndef candidate(title: str, snippet: str):\n    return DiscoveryCandidate(\n        disaster_id=1,\n        platform="facebook",\n        query="test",\n        url="https://facebook.com/example/posts/123",\n        title=title,\n        snippet=snippet,\n    )\n\n\ndef test_public_post_metadata_prefers_richer_text():\n    html = """\n    <html><head>\n      <meta name="description" content="Short indexed text">\n      <meta property="og:description"\n        content="Missing person Nima Tamang, age 65, last seen at Timure. Contact 9704485859.">\n    </head></html>\n    """\n    text = extract_public_post_text_from_html(html)\n    assert text is not None\n    assert "Nima Tamang" in text\n    assert "9704485859" in text\n    assert len(text) > len("Short indexed text")\n\n\ndef test_multiple_named_people_are_detected_from_one_post():\n    row = candidate(\n        "Person Missing Dorje Tamang and Pasang Tamang have been out of contact",\n        "Their last known location was Timure, Rasuwa.",\n    )\n    assert extract_candidate_people_names(row) == [\n        "Dorje Tamang",\n        "Pasang Tamang",\n    ]\n\n\ndef test_middle_dot_multi_person_text_does_not_turn_org_into_person():\n    row = candidate(\n        "New York teen, mother traveling in Nepal among missing",\n        "Missing person Whitney Hatfield · Linda Lester ↪ Travel Nurse R Us. 2y",\n    )\n    names = extract_candidate_people_names(row)\n    assert "Whitney Hatfield" in names\n    assert "Linda Lester" in names\n    assert all("Travel Nurse" not in item for item in names)\n\n\ndef test_full_public_post_text_improves_contact_prefill():\n    row = candidate(\n        "Missing person Nima Tamang",\n        "Nima Tamang is missing from Timure.",\n    )\n    prefill = extract_candidate_prefill(\n        row,\n        disaster(),\n        source_text=(\n            "Missing person Nima Tamang, age 65, last seen at Timure. "\n            "Please contact 9704485859 or 9862426561."\n        ),\n    )\n    assert prefill["age"] == 65\n    assert prefill["last_seen_location"] == "Timure"\n    assert prefill["public_contact_number"] == "9704485859, 9862426561"\n    assert "Public post text:" in prefill["identification_details"]\n\n\ndef test_plural_family_wording_flags_multiple_people():\n    row = candidate(\n        "Person Missing Kippa Lama, Dickey, and their sons",\n        "They were last known to be in Timure, Rasuwa.",\n    )\n    assert candidate_mentions_multiple_people(row)\n\n\ndef _create_event(client):\n    response = client.post(\n        "/admin/events",\n        data={\n            "code": "RF",\n            "name": "Rasuwa Flood",\n            "disaster_type": "flood",\n            "start_date": "2026-08-26",\n            "affected_locations": "Rasuwa\\nTimure",\n            "active": "on",\n        },\n        follow_redirects=False,\n    )\n    assert response.status_code == 303\n\n\ndef _add_manual_candidate(client, url, title, snippet):\n    response = client.post(\n        "/admin/discovery/manual",\n        data={\n            "disaster_id": "1",\n            "platform": "facebook",\n            "url": url,\n            "title": title,\n            "snippet": snippet,\n        },\n        follow_redirects=False,\n    )\n    assert response.status_code == 303\n\n\ndef _disable_public_fetch(monkeypatch):\n    async def no_text(_url):\n        return None\n\n    async def no_image(_url):\n        return None\n\n    monkeypatch.setattr(\n        "app.routes.admin.discover_public_post_text",\n        no_text,\n    )\n    monkeypatch.setattr(\n        "app.routes.admin.discover_public_post_image",\n        no_image,\n    )\n\n\ndef test_multi_person_source_can_create_two_entries_and_stays_relevant(\n    admin_client,\n    monkeypatch,\n):\n    from app.database import SessionLocal\n    from app.models import DiscoveryCandidate, Submission\n\n    _disable_public_fetch(monkeypatch)\n    _create_event(admin_client)\n    _add_manual_candidate(\n        admin_client,\n        "https://facebook.com/example/posts/multi123",\n        "Person Missing Dorje Tamang and Pasang Tamang have been out of contact",\n        "Their last known location was Timure, Rasuwa.",\n    )\n\n    page = admin_client.get("/admin/discovery/1")\n    assert page.status_code == 200\n    assert "Possible multiple missing people" in page.text\n    assert "Dorje Tamang" in page.text\n    assert "Pasang Tamang" in page.text\n\n    first = admin_client.post(\n        "/admin/discovery/1/submission",\n        data={\n            "name": "Dorje Tamang",\n            "last_seen_location": "Timure",\n        },\n        follow_redirects=False,\n    )\n    assert first.status_code == 303\n    assert "#person-entry-form" in first.headers["location"]\n\n    second = admin_client.post(\n        "/admin/discovery/1/submission",\n        data={\n            "name": "Pasang Tamang",\n            "last_seen_location": "Timure",\n        },\n        follow_redirects=False,\n    )\n    assert second.status_code == 303\n\n    with SessionLocal() as db:\n        candidate_row = db.get(DiscoveryCandidate, 1)\n        assert candidate_row.status == "relevant"\n        names = {\n            item.name\n            for item in db.query(Submission).all()\n        }\n        assert names == {"Dorje Tamang", "Pasang Tamang"}\n\n\ndef test_exact_duplicate_requires_attach_or_explicit_continue(\n    admin_client,\n    monkeypatch,\n):\n    from app.database import SessionLocal\n    from app.models import Disaster, MissingPerson, Source, Submission\n\n    _disable_public_fetch(monkeypatch)\n    _create_event(admin_client)\n\n    with SessionLocal() as db:\n        person = MissingPerson(\n            case_number="RF-0001",\n            disaster_id=1,\n            name="Nima Tamang",\n            last_seen_location="Timure",\n            published=False,\n        )\n        db.add(person)\n        db.commit()\n        person_id = person.id\n\n    _add_manual_candidate(\n        admin_client,\n        "https://facebook.com/example/posts/nima456",\n        "Person Missing Nima Tamang",\n        "Nima Tamang is missing from Timure.",\n    )\n\n    blocked = admin_client.post(\n        "/admin/discovery/1/submission",\n        data={\n            "name": "Nima Tamang",\n            "last_seen_location": "Timure",\n        },\n        follow_redirects=False,\n    )\n    assert blocked.status_code == 409\n\n    attached = admin_client.post(\n        "/admin/discovery/1/submission",\n        data={\n            "name": "Nima Tamang",\n            "last_seen_location": "Timure",\n            "duplicate_action": f"attach:{person_id}",\n        },\n        follow_redirects=False,\n    )\n    assert attached.status_code == 303\n\n    with SessionLocal() as db:\n        assert (\n            db.query(Source)\n            .filter(\n                Source.person_id == person_id,\n                Source.url == "https://facebook.com/example/posts/nima456",\n            )\n            .count()\n            == 1\n        )\n        assert db.query(Submission).count() == 0\n\n\ndef test_pending_duplicate_requires_explicit_continue(\n    admin_client,\n    monkeypatch,\n):\n    from app.database import SessionLocal\n    from app.models import Submission\n\n    _disable_public_fetch(monkeypatch)\n    _create_event(admin_client)\n\n    with SessionLocal() as db:\n        db.add(\n            Submission(\n                disaster_id=1,\n                kind="missing_report",\n                status="pending",\n                name="Rajan Shrestha",\n                last_seen_location="Timure",\n            )\n        )\n        db.commit()\n\n    _add_manual_candidate(\n        admin_client,\n        "https://facebook.com/example/posts/rajan789",\n        "Person Missing Rajan Shrestha",\n        "Rajan Shrestha is missing from Timure.",\n    )\n\n    blocked = admin_client.post(\n        "/admin/discovery/1/submission",\n        data={\n            "name": "Rajan Shrestha",\n            "last_seen_location": "Timure",\n        },\n        follow_redirects=False,\n    )\n    assert blocked.status_code == 409\n\n    continued = admin_client.post(\n        "/admin/discovery/1/submission",\n        data={\n            "name": "Rajan Shrestha",\n            "last_seen_location": "Timure",\n            "duplicate_action": "continue",\n        },\n        follow_redirects=False,\n    )\n    assert continued.status_code == 303\n\n    with SessionLocal() as db:\n        assert (\n            db.query(Submission)\n            .filter(Submission.name == "Rajan Shrestha")\n            .count()\n            == 2\n        )\n\n\ndef test_discovery_page_contains_scroll_restore_hooks(\n    admin_client,\n):\n    _create_event(admin_client)\n    _add_manual_candidate(\n        admin_client,\n        "https://facebook.com/example/posts/scroll123",\n        "Person Missing Nima Tamang",\n        "Nima Tamang is missing from Timure.",\n    )\n    page = admin_client.get(\n        "/admin/discovery?disaster_id=1&platform=facebook&view=review"\n    )\n    assert page.status_code == 200\n    assert "mp-discovery-scroll:" in page.text\n    assert "discovery-status-form" in page.text\n    assert "discovery-review-link" in page.text\n'}


def canonical(text: str) -> str:
    return text.replace("\r\n", "\n").replace("\r", "\n")


def digest(path: Path) -> str:
    text = path.read_text(encoding="utf-8")
    return hashlib.sha256(canonical(text).encode("utf-8")).hexdigest()


def main() -> int:
    root = Path.cwd()

    for rel, expected in EXPECTED.items():
        path = root / rel
        if not path.is_file():
            print(f"ABORTED: expected file missing: {rel}")
            return 2

        actual = digest(path)
        if actual != expected:
            print(f"ABORTED: local file differs from reviewed version: {rel}")
            print(f"Expected SHA-256: {expected}")
            print(f"Actual SHA-256:   {actual}")
            print("No files were changed.")
            return 3

    new_test = root / "tests/test_discovery_review_intelligence_upgrade.py"
    if new_test.exists():
        print("ABORTED: tests/test_discovery_review_intelligence_upgrade.py already exists.")
        print("No files were changed.")
        return 4

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = root / f".review-intelligence-backup-{stamp}"

    for rel in EXPECTED:
        source = root / rel
        target = backup / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)

    for rel, content in CONTENTS.items():
        target = root / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8", newline="\n")

    print("DISCOVERY REVIEW INTELLIGENCE UPGRADE APPLIED")
    print(f"Backup: {backup}")
    print("")
    print("Added:")
    print("- richer public-post text retrieval on discovery/review pages")
    print("- duplicate-name warning + attach-source workflow")
    print("- pending duplicate confirmation")
    print("- multi-person post detection + repeat-entry workflow")
    print("- discovery scroll-position restoration")
    print("- review form anchor after create/attach")
    print("")
    print("No database schema migration was required.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
